const EDITOR_VERSION = '1.12.1';

    function log() { /* replaced by pro/ui.js */ }

function hex(bytes) { return Array.from(bytes).map(b => b.toString(16).padStart(2, '0').toUpperCase()).join(' '); }

function printableASCII(bytes) { return Array.from(bytes).map(b => (b >= 32 && b <= 126) ? String.fromCharCode(b) : '.').join(''); }

    function setStatus() { /* replaced by pro/ui.js */ }

function bytesFromHex(s) { return new Uint8Array(s.replaceAll(' ', '').match(/.{1,2}/g).map(h => parseInt(h, 16))); }

const gattWriteQueue = [];

let gattWritePumpRunning = false;

function writeC304(label, payload, coalesceKey = null) {
      return new Promise(resolve => {
        if (coalesceKey) {
          const pending = gattWriteQueue.find(job => job.key === coalesceKey);
          if (pending) {
            pending.label = label;
            pending.payload = payload;
            pending.waiters.push(resolve);
            return;
          }
        }

        gattWriteQueue.push({ key: coalesceKey, label, payload, waiters: [resolve] });
        pumpGattWriteQueue();
      });
    }

async function pumpGattWriteQueue() {
      if (gattWritePumpRunning) return;
      gattWritePumpRunning = true;

      while (gattWriteQueue.length > 0) {
        const job = gattWriteQueue.shift();
        let ok = false;
        try {
          if (!state.c304) {
            log('ERROR: not connected - C304 characteristic not available');
          } else {
            log('TX ' + job.label + ': ' + hex(job.payload));
            if (state.c304.writeValueWithResponse) await state.c304.writeValueWithResponse(job.payload);
            else await state.c304.writeValue(job.payload);   // older Web Bluetooth implementations (Bluefy)
            ok = true;
          }
        } catch (err) {
          log('ERROR: BLE write failed for "' + job.label + '": ' + err);
        }
        job.waiters.forEach(resolve => resolve(ok));
      }

      gattWritePumpRunning = false;
    }

let connectBusy = false;

async function connectAll() {
      if (connectBusy || state.connected) {
        log('Connect ignored: ' + (state.connected ? 'already connected.' : 'a connection is being set up.'));
        return;
      }
      connectBusy = true;
      $('connectBtn').disabled = true;
      try {
        await connectNano();
        if (state.connected) {
          await syncMetadataAndState();
        }
      } finally {
        connectBusy = false;
        $('connectBtn').disabled = false;
      }
    }

async function connectNano() {
      try {
        if (!navigator.bluetooth) throw new Error('Web Bluetooth is not available. Use Chrome or Edge.');
        setStatus('Requesting device...');
        log('Requesting Nano Cortex...');

        const device = await navigator.bluetooth.requestDevice({ acceptAllDevices: true, optionalServices: SERVICE_UUIDS });
        state.device = device;
        device.addEventListener('gattserverdisconnected', onDisconnected);

        setStatus('Connecting...');
        log('Selected device: ' + (device.name || '(unnamed)'));

        const server = await device.gatt.connect();
        state.server = server;
        log('Connected. Searching A002/A003 for C304/C305...');

        state.c304 = null;
        state.c305 = null;

        // C304 / C305 are asked for by UUID: browsers report UUIDs in different forms (Bluefy on the iPhone e.g. in
        // capitals or as "C304"), so comparing the listed UUIDs as text is only the fallback.
        for (const serviceUUID of SERVICE_UUIDS) {
          if (state.c304 && state.c305) break;
          try {
            const service = await server.getPrimaryService(serviceUUID);
            log('Service accessible: ' + serviceUUID);
            try {
              state.c304 = await service.getCharacteristic(C304_UUID);
              state.c305 = await service.getCharacteristic(C305_UUID);
              log('Found C304 write and C305 notify characteristics');
              continue;
            } catch (err) {
              state.c304 = state.c305 = null;
            }
            const full = uuid => (/^[0-9a-f]{4}$/.test(uuid) ? '0000' + uuid + '-0000-1000-8000-00805f9b34fb' : uuid);
            const characteristics = await service.getCharacteristics();
            for (const ch of characteristics) {
              const uuid = full(ch.uuid.toLowerCase());
              log('Characteristic: ' + uuid);
              if (uuid === C304_UUID) { state.c304 = ch; log('Found C304 write characteristic'); }
              if (uuid === C305_UUID) { state.c305 = ch; log('Found C305 notify characteristic'); }
            }
          } catch (err) {
            log('Service unavailable ' + serviceUUID + ': ' + err.message);
          }
        }

        if (!state.c304 || !state.c305) throw new Error('C304/C305 not found under A002/A003');
        await state.c305.startNotifications();
        state.c305.addEventListener('characteristicvaluechanged', onC305);

        state.connected = true;
        // "Nano Cortex Controller": the hardware controller passes everything on to the Nano.
        state.viaController = /controller/i.test(device.name || '');
        setStatus(state.viaController ? 'Connected via controller' : 'Connected', true);
        log('C305 notifications enabled. Loading metadata and current preset state...');
      } catch (err) {
        log('Connect failed: ' + err.message);
        setStatus('Disconnected');
        // The list was closed without a device - often because the Nano was not in it: it only shows while nothing
        // else holds its one Bluetooth connection.
        if (err && err.name === 'NotFoundError') {
          showNotice('Nano not in the list?', 'The Nano shows up only while nothing else is connected to it.' + NL + NL +
            '• Close the Cortex Cloud app on your phone (or switch the phone’s Bluetooth off).' + NL +
            '• Close other tabs or windows with the editor, and the Nano Cortex Controller if it is on.' + NL +
            '• Wait about ten seconds and click Connect again.' + NL + NL +
            'If it still does not appear, switch the Nano off and on.');
        }
      }
    }

async function syncMetadataAndState() {
      log('Sync started');

      state.stateMode = 'metadata';
      state.feBytes = [];
      state.stateBytes = [];
      state.protocol.feSyncComplete = false;

      if (state.protocol.metadataLoaded) {
        log('Metadata already loaded for this session; skipping FE metadata request.');

        renderPresetSelect();
        beginPresetLoad();
        return;
      }

      await writeC304('FE metadata request', bytesFromHex('06 C0 08 03 01 00 00 00'));

      // Wait for the whole preset list (18 KB; its last packet is parsed at once), not a fixed time: through the
      // controller it can take longer than the 2.2 s used before, and a current-state request sent meanwhile got
      // the rest of the list mixed into the preset state.
      const started = Date.now();
      const next = () => {
        if (!state.connected) return;
        const quiet = Date.now() - Math.max(started, state.feLastPacketAt || 0);   // no packet for this long
        if (!state.protocol.feSyncComplete && quiet < 4000) {
          setTimeout(next, 100);
          return;
        }
        renderPresetSelect();
        beginPresetLoad();
      };
      setTimeout(next, 100);
    }

function beginPresetLoad() {
      resetMidiPickup();
      state.protocol.presetLoad = true;
      state.protocol.skipFXModelApply = false;
      cancelFXParamRefresh();

      if (state.presetLoadTimer) clearTimeout(state.presetLoadTimer);
      state.presetLoadTimer = setTimeout(() => {
        state.presetLoadTimer = null;
        log('Lade neue Preset-Daten (Refresh)...');
        requestCurrentPresetState();
      }, 450);
    }

async function requestCurrentPresetState() {
      if (state.stateTimer) clearTimeout(state.stateTimer);
      state.stateTimer = null;
      state.stateMode = 'current';
      state.stateBytes = [];
      await writeC304('Current preset state request', bytesFromHex('0C C0 08 03 18 01 20 01 28 01 01 00 00 00'));
    }

function onDisconnected() {
      state.connected = false;
      state.viaController = false;
      state.c304 = null;
      state.c305 = null;
      state.paramRefreshQueue = [];
      state.pendingParamBlock = null;
      if (state.pendingParamTimer) clearTimeout(state.pendingParamTimer);
      state.pendingParamTimer = null;
      state.paramRefreshDiscardPending = false;
      if (state.paramRefreshDrainTimer) clearTimeout(state.paramRefreshDrainTimer);
      state.paramRefreshDrainTimer = null;
      state.protocol.metadataLoaded = false;
      state.protocol.feSyncComplete = false;
      gattWriteQueue.splice(0).forEach(job => job.waiters.forEach(resolve => resolve(false)));
      resetExpRequests();
      abEnd();
      closeDeviceDialogs();
      state.inputMuted = state.outputMuted = null;
      state.settingsAsked = false;
      clearLocalEdit();
      renderMutes();
      setStatus('Disconnected');
      log('Disconnected.');
    }

function closeDeviceDialogs() {
      closeTuner(false);
      closeExpPanel();
      closeFootswitches();
      closeLibraryBrowser();
      closeMic();
      copyDialog.busy = false;
      closeCopyPreset();
      if (eqView) eqView.closeDialog();
      $('mc6Overlay').hidden = true;
      $('shareOverlay').hidden = true;
      renderShared();   // the shared presets stay open: without the Nano they show what they need
      if (!$('slotOverlay').hidden && $('slotCancel').onclick) $('slotCancel').onclick();
      if (!$('askOverlay').hidden && $('askCancel').onclick) $('askCancel').onclick();
    }

function onC305(event) {
      const data = new Uint8Array(event.target.value.buffer.slice(0));
      if (frameType(data) === MSG.TunerMetering) { handleTunerMetering(data); return; }
      if (frameType(data) === MSG.ControllerSwitch) { controllerSwitch(data); return; }
      log('RX C305: ' + hex(data.slice(0, 24)) + (data.length > 24 ? ' ...' : ''));

      if (data.length === 0) return;

      if (isCabIRParamRefreshResponse(data)) {
        handleCabIRParamRefreshResponse(data);
        return;
      }

      if (isFXParamRefreshResponse(data)) {
        handleFXParamRefreshResponse(data);
        return;
      }

      if (handleTypedMessage(data)) return;

      if (isFEStreamPacket(data)) {
        // The last packet of a reply carries 0x80 in its second byte: the reply is parsed at once then (the timers
        // remain for a lost last packet).
        const last = (data[1] & 0x80) === 0x80;
        if (state.stateMode === 'library') {
          for (const b of data.slice(2)) state.libraryBytes.push(b);
          if (state.libraryTimer) clearTimeout(state.libraryTimer);
          state.libraryTimer = setTimeout(() => parseLibraryContent(state.libraryBytes), 1500);
        } else if (state.stateMode === 'current') {
          appendCurrentStatePayload(data);
          if (last) {
            if (state.stateTimer) clearTimeout(state.stateTimer);
            parseBufferedCurrentState();
          } else {
            scheduleCurrentStateParse();
          }
        } else {
          appendFEStreamPayload(data);
          state.feLastPacketAt = Date.now();
          if (last) {
            if (state.feTimer) clearTimeout(state.feTimer);
            parseBufferedFE();
          } else {
            scheduleFEParse();
          }
        }
        return;
      }

      parseCurrentPresetState(data);
    }

function appendCurrentStatePayload(data) {
      const payload = data.slice(2);
      for (const b of payload) state.stateBytes.push(b);
    }

const presetStateWaiters = [];

function scheduleCurrentStateParse() {
      if (state.stateTimer) clearTimeout(state.stateTimer);
      state.stateTimer = setTimeout(parseBufferedCurrentState, 2000);   // only if the last packet got lost
    }

function parseBufferedCurrentState() {
      resetMidiPickup();
      if (state.stateBytes.length === 0) return;

      const bytes = state.stateBytes.slice();
      log('CURRENT STATE FULL HEX: ' + hex(bytes));
      log('CURRENT STATE FULL ASCII: ' + printableASCII(bytes));
      const fields = parseProtoFields(bytes);

      const captureSlot = fields[11] && fields[11][0] ? fields[11][0].value : 0;

      state.capture.selectedSlot = captureSlot;
      state.capture.on = captureSlot > 0;

      if (captureSlot > 0) {
        state.capture.lastActiveSlot = captureSlot;
      }

      state.cabIR.on = Boolean(fields[12] && fields[12][0]);
      state.cabIR.stateSlot = fields[12] && fields[12][0] ? fields[12][0].value : 0;   // cab slot 1-5, 0 = bypass

      state.amp.gain = fields[3] && fields[3][0] ? fields[3][0].value : 0;
      state.amp.level = fields[4] && fields[4][0] ? fields[4][0].value : 0;
      state.amp.bass = fields[5] && fields[5][0] ? fields[5][0].value : 0;
      state.amp.mid = fields[6] && fields[6][0] ? fields[6][0].value : 0;
      state.amp.treble = fields[7] && fields[7][0] ? fields[7][0].value : 0;

      state.gate.on = !(fields[54] && fields[54][0]);

      // 9 bankSelector (1-5), 11 neuralCaptureSelector (position 1-5 in bank, 0 = bypass).
      // The app derives the absolute capture slot from them: (bank-1)*5 + position.
      const bank = Math.min(5, Math.max(1, fields[9] && fields[9][0] ? fields[9][0].value : 1));
      state.capture.activeSlot = captureSlot > 0 ? (bank - 1) * 5 + captureSlot : null;

      // StateResponseMessage: 13 currentPresetIndex, 14/15/38/39 footswitch slots,
      // 41 currentPresetDirty. The device omits zero values.
      const varintField = (n, fallback) => fields[n] && fields[n][0] && fields[n][0].wire === 0 ? fields[n][0].value : fallback;
      state.selectedPreset = varintField(13, 0) + 1;
      state.presetSlots = { a1: varintField(14, 0), b1: varintField(15, 0), a2: varintField(38, 0), b2: varintField(39, 0) };
      state.fourPresetMode = Boolean(varintField(37, 0));
      state.presetDirty = Boolean(varintField(41, 0));
      const tunerFreq = fields[46] && fields[46][0];
      if (tunerFreq && tunerFreq.wire === 5) {
        state.tuner.baseFrequency = Math.round(new DataView(Uint8Array.from(tunerFreq.raw).buffer).getFloat32(0, true)) || 440;
      }
      state.tuner.muted = Boolean(varintField(63, 0));
      log('Current preset: ' + state.selectedPreset + (state.presetDirty ? ' (edited)' : ''));
      if ((!$('expOverlay').hidden || state.mc6.mixSlot >= 0) && (state.exp.preset !== state.selectedPreset || !state.exp.loaded)) requestExpAssignments();

    if (fields[31] && fields[31][0]) {
      log('FX enable field 31 raw: ' + hex(fields[31][0].raw));
    }

    if (fields[44] && fields[44][0]) {
      const rawCaptureVolume = fields[44][0].value;
      const captureDb = captureRawToDb(rawCaptureVolume);

      state.captureVolumeDb = captureDb;
      setCaptureVolumeUI(captureDb);

      log('Current capture volume: ' + captureDb.toFixed(1) + ' dB raw=' + rawCaptureVolume);
    }

      const capture = fields[32] && fields[32][0] ? parseSelectedCaptureState(fields[32][0].raw) : null;
      const ir = fields[33] && fields[33][0] ? parseSelectedIRState(fields[33][0].raw) : null;

      if (capture) {

          const resolvedName =
              capture.name &&
              !/^capture\s+\d+$/i.test(capture.name)
                  ? capture.name
                  : state.currentCapture.name;

          state.currentCapture = {
              name: resolvedName || '',
              id: capture.id || '',
              inBank: Array.from(state.captureNames.values()).some(
                  name =>
                      String(name).trim().toLowerCase() ===
                      String(resolvedName || '').trim().toLowerCase()
              )
          };

          const resolvedCaptureSlot = currentCaptureSlotIndex();
          if (resolvedCaptureSlot) {
            state.capture.selectedSlot = resolvedCaptureSlot;
            state.capture.lastActiveSlot = resolvedCaptureSlot;
          }
      }

      if (ir) {

          const resolvedShortName =
              ir.shortName &&
              !/^ir\s+\d+$/i.test(ir.shortName)
                  ? ir.shortName
                  : state.currentIR.shortName;

          state.currentIR = {
              shortName: resolvedShortName || '',
              fullName: ir.fullName || state.currentIR.fullName || '',
              inBank: Array.from(state.irNames.values()).some(
                  name =>
                      String(name).trim().toLowerCase() ===
                      String(resolvedShortName || '').trim().toLowerCase()
              )
          };

        const parsedCabIR = parseCabIRNameParts(state.currentIR.fullName || state.currentIR.shortName);
        state.cabIR.micFromState = Boolean(parsedCabIR.mic);
        if (!state.protocol.skipFXModelApply || state.protocol.presetLoad) {
          if (parsedCabIR.mic) state.cabIR.mic = parsedCabIR.mic;
          if (parsedCabIR.position !== null) state.cabIR.position = parsedCabIR.position;
        }
        // After a mic change: the state names the IR the preset plays now ("cab/mic/position"), the reliable check.
        // (The cab settings reply is not: it can name another position than the preset plays - seen in a log.)
        const micCheck = cabMicLive.check;
        if (micCheck && parsedCabIR.mic && !cabMicLiveActive()) {
          cabMicLive.check = null;
          const pos = parsedCabIR.position !== null ? parsedCabIR.position : 1;
          const took = sameName(parsedCabIR.mic, micCheck.mic) && pos === micCheck.position;
          log('Cab mic in the state: ' + parsedCabIR.mic + ', position ' + pos + (took ? ' - as chosen' : ' - chosen was ' + micCheck.mic + ', position ' + micCheck.position));
          if (!took) {
            state.cabIR.mic = parsedCabIR.mic;
            state.cabIR.position = pos;
            toast('The Nano plays ' + parsedCabIR.mic + ', position ' + pos + ' – it did not take ' + micCheck.mic + ', position ' + micCheck.position + '.', 'error', 8000);
          }
        }
        state.cabIR.selectedSlot = currentIRSlotIndex();

        if (state.cabIR.selectedSlot > 0) {
          state.cabIR.lastActiveSlot = state.cabIR.selectedSlot;
        }

        log('Current cab/IR: ' + state.currentIR.shortName);
      }

      const isPresetLoad = state.protocol.presetLoad;
      applyFXModelsFromCurrentState(fields);
      applyFXEnabledStatesFromCurrentState(fields);
      if (isPresetLoad) discardActiveCachedFXParams();

      levelMarkCheck();
      render();
      presetStateWaiters.slice().forEach(waiter => waiter());
      if (state.inputMuted === null && !state.settingsAsked) { state.settingsAsked = true; setTimeout(requestSettings, 700); }   // the two mutes

      log('CURRENT STATE BUFFER len=' + bytes.length);
      log('CURRENT STATE capture=' + (state.currentCapture.name || 'unknown') + ', ir=' + (state.currentIR.shortName || 'unknown'));

      state.stateBytes = [];
      state.stateMode = 'idle';

      state.protocol.presetLoad = false;

      requestCabIRParamRefresh();
      queueFXParamRefreshes();

      if (!state.library.requested) {
        state.library.requested = true;
        setTimeout(requestLibraryContent, 2500);
      }
    }

function applyFXModelsFromCurrentState(fields) {
      // Capture/cab-IR/mic changes trigger a confirmatory state re-read,
      // but can't actually change which FX model is loaded. The device may
      // transiently report stale/wrong model IDs during these transitions
      // (especially for Transpose and other 3-byte-ID models), so we skip
      // model re-application entirely for those re-reads.
      if (state.protocol.skipFXModelApply && !state.protocol.presetLoad) {
        state.protocol.skipFXModelApply = false;
        log('FX model apply skipped (confirmatory re-read)');
        return;
      }
      state.protocol.skipFXModelApply = false;

      // After a preset change the response is authoritative: a missing or
      // unknown model field means the slot no longer holds the old model.
      const isPresetLoad = state.protocol.presetLoad;

      const fieldMap = {
        pre1: 48,
        pre2: 49,
        post1: 50,
        post2: 51,
        post3: 52
      };

      Object.entries(fieldMap).forEach(([blockKey, fieldNumber]) => {
        const entry = fields[fieldNumber] && fields[fieldNumber][0] ? fields[fieldNumber][0] : null;
        const block = state.blocks[blockKey];

        if (!entry || !block) {
          // Field missing from current-state response — this can happen
          // transiently during capture/cab-IR toggles. If we already have
          // a valid model loaded, keep it rather than wiping to None.
          if (!block || isPresetLoad || block.model === 'None') setBlockToNone(blockKey);
          return;
        }

        const idHex = hex(entry.raw).replaceAll(' ', '');
        log(block.title + ' raw current-state model field ' + fieldNumber + ': ' + idHex);

        const model = findModelByCurrentStateID(block, idHex);

        if (!model) {
          log(block.title + ' current model ID not mapped: ' + idHex);
          if (isPresetLoad || block.model === 'None') setBlockToNone(blockKey);
          return;
        }

        // Reset parameters when the model or preset changes. For unrelated
        // state re-reads, preserve current values and try the per-preset cache
        // only when this block has not been read for the selected preset.
        const modelChanged = block.model !== model.name;
        const presetChanged = block.paramsPreset !== state.selectedPreset;
        if (modelChanged || (isPresetLoad && presetChanged)) {
          block.model = model.name;
          block.params = structuredClone(model.params || []);
          block.paramsLoaded = false;
          block.paramsFromCache = false;
          block.paramsPreset = state.selectedPreset;
          block.originalFloats = null;
          block.originalModel = null;
          block.originalPreset = null;
          block.fxPresetActive = -1;
          const restored = restoreFxParamCache(blockKey, block);
          log(block.title + (modelChanged ? ' model changed to: ' : ' preset changed, model unchanged: ') + model.name + ' [' + idHex + ']' + (restored ? ' (cached values restored)' : ''));
        } else {
          log(block.title + ' model unchanged: ' + model.name);
          if (!block.paramsLoaded || block.paramsPreset !== state.selectedPreset) restoreFxParamCache(blockKey, block);
        }
      });
    }

const fxSwitch = { switched: {}, reported: {}, preset: 0 };

function applyFXEnabledStatesFromCurrentState(fields) {
      const entry = fields[31] && fields[31][0] ? fields[31][0] : null;
      if (!entry || !entry.raw || entry.raw.length < 5) {
        log('FX bypass states not found.');
        return;
      }

      const keys = ['pre1', 'pre2', 'post1', 'post2', 'post3'];
      const otherPreset = fxSwitch.preset !== state.selectedPreset;
      fxSwitch.preset = state.selectedPreset;

      keys.forEach((key, index) => {
        const reported = entry.raw[index] === 0, switched = fxSwitch.switched[key];
        if (otherPreset || reported !== fxSwitch.reported[key] || reported === switched) {
          delete fxSwitch.switched[key];   // the report moved or agrees: it counts
          state.blocks[key].on = reported;
        } else if (switched !== undefined) {
          log(state.blocks[key].title + ' reported ' + (reported ? 'on' : 'off') + ', switched ' + (switched ? 'on' : 'off') + ' - stays (expression pedal?)');
          state.blocks[key].on = switched;
        } else {
          state.blocks[key].on = reported;
        }
        fxSwitch.reported[key] = reported;
      });

      log('FX bypass states: ' + keys.map((key, i) => key + '=' + (entry.raw[i] === 0 ? 'on' : 'off')).join(', '));
    }

function discardActiveCachedFXParams() {
      FX_BLOCK_KEYS.forEach(key => {
        const block = state.blocks[key];
        if (!block || !block.on || !block.paramsFromCache) return;

        const model = block.models.find(entry => entry.name === block.model);
        block.params = structuredClone(model && model.params || []);
        block.paramsLoaded = false;
        block.paramsFromCache = false;
        block.cachedAt = 0;
        block.originalFloats = null;
        block.originalModel = null;
        block.originalPreset = null;
        block.fxPresetActive = -1;
        log(block.title + ' cached values discarded for active preset load; waiting for live readback.');
      });
    }

function currentIRSlotIndex() {
      const current = String(state.currentIR.shortName || '').trim().toLowerCase();

      for (let i = 1; i <= 5; i++) {
        const name = String(state.irNames.get(i) || '').trim().toLowerCase();
        if (name && current && name === current) return i;
      }

      const select = $('irSelect');
      if (select && select.value !== 'library') return Number(select.value);

      return null;
    }

function currentCaptureSlotIndex() {
      const current = String(state.currentCapture.name || '').trim().toLowerCase();
      if (!current) return null;

      for (let i = 1; i <= 25; i++) {
        const name = String(state.captureNames.get(i) || '').trim().toLowerCase();
        if (name && name === current) return i;
      }

      return null;
    }

function parseCabIRNameParts(fullName) {
      const parts = String(fullName || '').split('/').map(x => x.trim()).filter(Boolean);

      if (parts.length >= 3) {
        const posRaw = Number(parts[parts.length - 1]);
        const mic = parts[parts.length - 2];

        return {
          baseName: parts.slice(0, parts.length - 2).join('/'),
          mic,
          position: Number.isFinite(posRaw) ? posRaw + 1 : null
        };
      }

      return {
        baseName: String(fullName || ''),
        mic: null,
        position: null
      };
    }

const CAB_LEVEL_NEGATIVE_POWER = 0.2841331;

function cabIRLevelDbToNormalized(db) {
      const value = clamp(Number(db), -96, 12);

      if (value <= 0) {
        // Calibrated to the reported -7.5 dB Cloud readback for this Cab/IR value.
        return clamp(0.66212219 * Math.pow((value + 96) / 96, 1 / CAB_LEVEL_NEGATIVE_POWER), 0, 0.66212219);
      }

      return clamp(0.66212219 + (value / 12) * (1 - 0.66212219), 0, 1);
    }

function cabIRLevelNormalizedToDb(normalized) {
      const n = clamp(Number(normalized), 0, 1);

      if (n <= 0.66212219) {
        return Math.pow(n / 0.66212219, CAB_LEVEL_NEGATIVE_POWER) * 96 - 96;
      }

      return ((n - 0.66212219) / (1 - 0.66212219)) * 12;
    }

function cabIRRangeToNormalized(value, min, max, power = 1) {
      const scaled = clamp((Number(value) - min) / (max - min), 0, 1);
      return Math.pow(scaled, 1 / power);
    }

function cabIRNormalizedToRange(normalized, min, max, step, power = 1) {
      return roundToStep(min + Math.pow(clamp(Number(normalized), 0, 1), power) * (max - min), step || 1);
    }

function cabIRValueToNormalized(key, value) {
      if (key === 'level') return cabIRLevelDbToNormalized(value);
      const [min, max, , power = 1] = CAB_RANGES[key];
      return cabIRRangeToNormalized(value, min, max, power);
    }

function cabIRNormalizedToValue(key, normalized) {
      if (key === 'level') return cabIRLevelNormalizedToDb(normalized);
      const [min, max, step, power = 1] = CAB_RANGES[key];
      return cabIRNormalizedToRange(normalized, min, max, step, power);
    }

async function selectCaptureSlot(slotNumber) {
      const slot = Number(slotNumber);
      if (!Number.isFinite(slot) || slot < 0 || slot > 25) return;

      state.capture.selectedSlot = slot;
      state.capture.on = slot !== 0;

      if (slot > 0) {
        state.capture.lastActiveSlot = slot;
      }

      await writeC304(
        slot === 0 ? 'Capture bypass' : 'Capture slot select ' + slot,
        new Uint8Array([0x08, 0xC0, 0x18, 0x01, 0x20, slot, 0x1C, 0x00, 0x00, 0x00])
      );

      renderCaptureIR();
      state.protocol.skipFXModelApply = true;
      setTimeout(requestCurrentPresetState, 300);
    }

async function selectCabIRSlot(slotNumber) {
      const slot = Number(slotNumber);
      if (!Number.isFinite(slot) || slot < 0 || slot > 5) return;

      state.cabIR.selectedSlot = slot;
      state.cabIR.on = slot !== 0;
      state.cabIR.micPending = null;

      if (slot > 0) {
        state.cabIR.lastActiveSlot = slot;
      }

      await writeC304(
        slot === 0 ? 'Cab/IR bypass' : 'Cab/IR slot select ' + slot,
        new Uint8Array([0x08, 0xC0, 0x18, 0x03, 0x20, slot, 0x1C, 0x00, 0x00, 0x00])
      );

      renderCaptureIR();
      state.protocol.skipFXModelApply = true;
      setTimeout(requestCurrentPresetState, 300);

      if (slot > 0) {
        // Wait for the current-state request above to round-trip and finish
        // parsing (it buffers notifications for ~600ms) before asking for
        // params, so this reads the confirmed slot rather than the optimistic one.
        setTimeout(requestCabIRParamRefresh, 1300);
      }
    }

async function requestCabIRParamRefresh() {
      if (!state.cabIR.on) {
        log('Cab/IR param refresh skipped: Cab/IR is bypassed.');
        return;
      }
      const slot = currentIRSlotIndex();

      if (!slot || slot < 1 || slot > 5) {
        log('Cab/IR param refresh skipped: current slot is library/unknown.');
        return;
      }

      state.cabIR.selectedSlot = slot;
      state.cabIR.paramsLoaded = false;

      await writeC304(
        'Cab/IR param refresh slot ' + slot,
        new Uint8Array([0x08, 0xC0, 0x18, 0x00, 0x20, slot - 1, 0x5F, 0x00, 0x00, 0x00])
      );
    }

function isCabIRParamRefreshResponse(data) {
      return data.length > 20 && frameType(data) === MSG.RetrievePresetCabinetSettingsLiteResponse;
    }

function handleCabIRParamRefreshResponse(data) {
      // The reply: 5 the factory IR { 1: index, 2: cab, 3: position (0-based, left out = 0), 4: mic }, 7 the mics this
      // cab offers (repeated - they differ from cab to cab: a bass cab had Condenser U47, Dynamic 421, Dynamic 52,
      // Dynamic 57, Ribbon 10), 8 level / high pass / low pass.
      const top = parseProtoFields(data.slice(2, data.length - 4));
      let cabName = '', mic = null, position = null;
      const cabEntry = top[5] && top[5].find(entry => entry.wire === 2);
      if (cabEntry) {
        const cab = parseProtoFields(cabEntry.raw);
        cabName = firstString(cab, 2) || '';
        mic = firstString(cab, 4) || null;
        if (mic) position = cab[3] && cab[3][0] && cab[3][0].wire === 0 ? cab[3][0].value + 1 : 1;
      }
      const mics = (top[7] || []).filter(entry => entry.wire === 2).map(entry => decodeText(entry.raw).trim()).filter(Boolean);
      if (cabName && mics.length) state.cabIR.micsByCab[cabName.trim().toLowerCase()] = mics;
      if (!mic) {   // replies that carry it as a "cab/mic/pos" string
        const parts = parseCabIRNameParts(printableASCII(data));
        mic = parts.mic;
        position = parts.position;
      }
      // Mic and position of the loaded cab come from the state (what the preset plays); this reply only fills in when
      // the state had none, and not while a newer choice is on its way to the Nano.
      if (!state.cabIR.micFromState && !cabMicLiveActive() && (!cabName || sameName(cabName, state.currentIR.shortName))) {
        if (mic) state.cabIR.mic = mic;
        if (position !== null) state.cabIR.position = position;
      }

      const paramBlob = extractCabIRParamBlob(data);

      if (!paramBlob) {
        log('Cab/IR parameter response received but no param blob found.');
        renderCaptureIR();
        return;
      }

      const values = parseCabIRParamBlob(paramBlob);

      if (values.levelNorm !== null) state.cabIR.levelDb = cabIRLevelNormalizedToDb(values.levelNorm);
      if (values.highPassNorm !== null) state.cabIR.highPassHz = cabIRNormalizedToRange(values.highPassNorm, 20, 800, 1, 1.68);
      if (values.lowPassNorm !== null) state.cabIR.lowPassHz = cabIRNormalizedToRange(values.lowPassNorm, 1000, 20000, 1, 1.68);

      state.cabIR.paramsLoaded = true;

      log(
        'Cab/IR params loaded: level=' + state.cabIR.levelDb.toFixed(1) +
        ' dB, HPF=' + Math.round(state.cabIR.highPassHz) +
        ' Hz, LPF=' + Math.round(state.cabIR.lowPassHz) +
        ' Hz, mic=' + state.cabIR.mic +
        ', position=' + state.cabIR.position
      );

      renderCaptureIR();
    }

function extractCabIRParamBlob(data) {
      for (let i = 0; i + 2 < data.length; i++) {
        const len = data[i + 1];
        if (data[i] === 0x42 && len >= 5 && len <= 15 && len % 5 === 0 &&
            [0x0D, 0x15, 0x1D].includes(data[i + 2]) && i + 2 + len <= data.length) {
          return data.slice(i + 2, i + 2 + len);
        }
      }

      return null;
    }

function parseCabIRParamBlob(blob) {
      // Omitted fields are 0.0 (protobuf default).
      const out = {
        levelNorm: 0,
        highPassNorm: 0,
        lowPassNorm: 0
      };

      for (let i = 0; i + 4 < blob.length;) {
        const tag = blob[i++];

        if ((tag === 0x0D || tag === 0x15 || tag === 0x1D) && i + 4 <= blob.length) {
          const value = new DataView(blob.buffer, blob.byteOffset + i, 4).getFloat32(0, true);
          if (tag === 0x0D) out.levelNorm = value;
          if (tag === 0x15) out.highPassNorm = value;
          if (tag === 0x1D) out.lowPassNorm = value;
          i += 4;
        } else {
          break;
        }
      }

      return out;
    }

function presetUnsaved() { return state.presetDirty || state.localEdit; }

function markLocalEdit() {
      if (state.localEdit || !state.connected) return;
      state.localEdit = true;
      renderPresetSelect();
    }

function clearLocalEdit() {
      state.localEdit = false;
      state.cabIR.micPending = null;
    }

async function setCabIRFloatParam(label, paramId, normalized) {
      markLocalEdit();
      await writeC304(
        'Cab/IR ' + label,
        new Uint8Array([0x09, 0xC0, paramId, ...float32LE(clamp(Number(normalized), 0, 1)), 0x5E, 0x00, 0x00, 0x00]),
        'cab-param:' + paramId
      );
    }

async function setCabIRLevelDb(db) {
      const value = clamp(Number(db), -96, 12);
      state.cabIR.levelDb = value;
      await setCabIRFloatParam('level ' + value.toFixed(1) + ' dB', 0x2D, cabIRLevelDbToNormalized(value));
    }

async function setCabIRHighPassHz(hz) {
      const value = clamp(Number(hz), 20, 800);
      state.cabIR.highPassHz = value;
      await setCabIRFloatParam('high pass ' + Math.round(value) + ' Hz', 0x35, cabIRRangeToNormalized(value, 20, 800, 1.68));
    }

async function setCabIRLowPassHz(hz) {
      const value = clamp(Number(hz), 1000, 20000);
      state.cabIR.lowPassHz = value;
      await setCabIRFloatParam('low pass ' + Math.round(value) + ' Hz', 0x3D, cabIRRangeToNormalized(value, 1000, 20000, 1.68));
    }

async function setCabIRMicPosition(mic, position) {
      if (!isFactoryCabIR()) {
        log('Cab mic/position ignored: current IR is not a factory cab slot.');
        return;
      }

      const cabName = String(state.currentIR.shortName || '').trim();
      const micName = String(mic || state.cabIR.mic || '').trim();

      if (!cabName || !micName) {
        log('Cab mic/position ignored: missing cab or mic name.');
        return;
      }

      const pos = clamp(Math.round(Number(position || state.cabIR.position || 1)), 1, 6);
      const posZero = pos - 1;

      state.cabIR.mic = micName;
      state.cabIR.position = pos;
      renderCaptureIRExtraParams();

      const cabBytes = Array.from(new TextEncoder().encode(cabName));
      const micBytes = Array.from(new TextEncoder().encode(micName));
      const innerLen = 8 + cabBytes.length + micBytes.length;

      const payload = new Uint8Array([
        0x00,
        0xC0,
        0x1A,
        innerLen,
        0x08,
        0x00,
        0x12,
        cabBytes.length,
        ...cabBytes,
        0x18,
        posZero,
        0x22,
        micBytes.length,
        ...micBytes,
        0x5E,
        0x00,
        0x00,
        0x00
      ]);
      payload[0] = payload.length - 2;

      markLocalEdit();
      state.cabIR.micPending = { cab: cabName, mic: micName, position: pos };   // goes into the cab slot with the next save
      await writeC304('Cab mic/position ' + micName + ' pos ' + pos, payload);
      scheduleCabMicLive();
    }

const cabMicLive = { timer: null, busy: false, again: false, check: null, written: null, writtenSlot: 0 };

function scheduleCabMicLive() {
      clearTimeout(cabMicLive.timer);
      cabMicLive.timer = setTimeout(runCabMicLive, 350);
    }

async function runCabMicLive() {
      cabMicLive.timer = null;
      if (cabMicLive.busy) { cabMicLive.again = true; return; }
      const want = state.cabIR.micPending;
      if (!want || !state.connected || !state.cabIR.on) return;
      const slot = state.cabIR.stateSlot;
      if (!(slot >= 1 && slot <= 5) || !sameName(state.irNames.get(slot), want.cab)) {
        log('Cab mic/position: "' + want.cab + '" is in no cab slot of this preset - it is written with Save.');
        return;
      }
      cabMicLive.busy = true;
      try {
        const result = await writeCabMicToSlot(want, slot);
        if (result.problem) { toast('Mic not changed: ' + result.problem + '.', 'error', 6000); return; }
        cabMicLive.written = want; cabMicLive.writtenSlot = slot;
        if (state.cabIR.micPending === want) cabMicLive.check = want;   // compared with the Nano's read-back
        state.protocol.skipFXModelApply = true;
        setTimeout(requestCurrentPresetState, 300);   // the state read then asks for the cab values of the slot
      } finally {
        cabMicLive.busy = false;
        if (cabMicLive.again) { cabMicLive.again = false; scheduleCabMicLive(); }
      }
    }

const cabMicLiveActive = () => Boolean(cabMicLive.timer || cabMicLive.busy);

async function storeCabMic() {
      clearTimeout(cabMicLive.timer); cabMicLive.timer = null;   // the save writes it now
      if (cabMicLive.busy) await waitUntil(() => !cabMicLive.busy, 8000);
      const want = state.cabIR.micPending;
      if (!want) return null;
      if (!state.cabIR.on || !isFactoryCabIR() || !sameName(state.currentIR.shortName, want.cab)) { state.cabIR.micPending = null; return null; }
      const what = want.mic + ', position ' + want.position;
      const item = await findInLibrary(['irFactory'], [want.cab]);
      if (!item) return { problem: 'the cab “' + want.cab + '” was not found in the Nano\'s library, so ' + what + ' was not stored' };
      // the slot of this preset if it holds this cab - else the cab comes from the library and needs a slot
      let slot = state.cabIR.stateSlot;
      if (!(slot >= 1 && slot <= 5) || !sameName(state.irNames.get(slot), want.cab)) slot = await chooseSlot('cab', want.cab + ' (' + what + ')');
      if (!slot) return { problem: 'no cab slot was chosen, so ' + what + ' was not stored' };

      if (cabMicLive.written !== want || cabMicLive.writtenSlot !== slot) {   // not already in the slot from the click
        const result = await writeCabMicToSlot(want, slot, item);
        if (result.problem) return result;
      }
      state.cabIR.micPending = null;
      return { slot, text: 'Cab slot ' + slot + ' now holds ' + want.cab + ' with ' + what + '.' };
    }

async function writeCabMicToSlot(want, slot, item) {
      const what = want.mic + ', position ' + want.position;
      if (!item) item = await findInLibrary(['irFactory'], [want.cab]);
      if (!item) return { problem: 'the cab “' + want.cab + '” was not found in the Nano\'s library, so ' + what + ' was not stored' };
      if (state.pendingCabAssignment) await waitUntil(() => !state.pendingCabAssignment, 6000);

      const nameBytes = Array.from(new TextEncoder().encode(want.cab)), micBytes = Array.from(new TextEncoder().encode(want.mic));
      const identifier = [0x08, ...encodeVarint(item.index), 0x12, ...encodeVarint(nameBytes.length), ...nameBytes,
        0x18, want.position - 1, 0x22, ...encodeVarint(micBytes.length), ...micBytes];
      const frame = buildFrame([0x18, ...encodeVarint(slot - 1), 0x22, ...encodeVarint(identifier.length), ...identifier], MSG.SetCabinetSlotContentRequest);
      if (frame.length - 2 > 255) return { problem: 'the cab name is too long, so ' + what + ' was not stored' };

      const answer = new Promise(resolve => {
        state.pendingCabAssignment = { slot, name: want.cab, resolve };
        setTimeout(() => resolve({ ok: false, message: 'the Nano did not answer' }), 6000);
      });
      if (!await writeC304('Cab slot ' + slot + ': "' + want.cab + '" with ' + what, frame)) {
        state.pendingCabAssignment = null;
        return { problem: 'the Bluetooth write failed, so ' + what + ' was not stored' };
      }
      const result = await answer;
      if (state.pendingCabAssignment && state.pendingCabAssignment.resolve) state.pendingCabAssignment = null;
      if (!result.ok) return { problem: 'the Nano did not take ' + what + ' into cab slot ' + slot + ' (' + result.message + ')' };

      // the slot again, so that the preset has what is in it now (as after loading a cab from the library)
      state.irNames.set(slot, want.cab);
      state.cabIR.stateSlot = state.cabIR.selectedSlot = state.cabIR.lastActiveSlot = slot;
      await writeC304('Cab/IR slot select ' + slot, new Uint8Array([0x08, 0xC0, 0x18, 0x03, 0x20, slot, 0x1C, 0x00, 0x00, 0x00]));
      await new Promise(r => setTimeout(r, 500));
      return {};
    }

function setBlockToNone(blockKey) {
      const block = state.blocks[blockKey];
      if (!block) return;
      const none = block.models.find(m => m.name === 'None');
      block.model = 'None';
      block.params = none && none.params ? structuredClone(none.params) : [];
      block.on = false;
      block.paramsLoaded = false;
      block.paramsFromCache = false;
      block.paramsPreset = null;
    }

function findModelByCurrentStateID(block, idHex) {
      const clean = String(idHex || '').toUpperCase();

      const direct = block.models.find(model =>
        model.id && hex(model.id).replaceAll(' ', '').toUpperCase() === clean
      );

      if (direct) return direct;

      return null;
    }

function fxParamCacheKey(blockKey, block, preset = state.selectedPreset) {
      const model = block && block.models.find(entry => entry.name === block.model);
      const modelId = model && model.id ? hex(model.id).replaceAll(' ', '') : block && block.model;
      const deviceName = state.device && state.device.name ? state.device.name : NANO_NAME_PREFIX;
      return JSON.stringify([deviceName, preset, blockKey, modelId]);
    }

function readFxParamCache() {
      try { return JSON.parse(localStorage.getItem(FX_PARAM_CACHE_KEY) || '{}') || {}; }
      catch (e) { return {}; }
    }

function saveFxParamCache(blockKey, floats) {
      const block = state.blocks[blockKey];
      if (!block || block.model === 'None' || !Array.isArray(floats) || floats.length !== block.params.length) return;
      try {
        const cache = readFxParamCache();
        cache[fxParamCacheKey(blockKey, block)] = { model: block.model, floats: floats.slice(), savedAt: Date.now() };
        const entries = Object.entries(cache).sort((a, b) => Number(b[1].savedAt || 0) - Number(a[1].savedAt || 0)).slice(0, 500);
        localStorage.setItem(FX_PARAM_CACHE_KEY, JSON.stringify(Object.fromEntries(entries)));
      } catch (e) { /* local cache is optional */ }
    }

function saveCurrentFxParamCache(blockKey) {
      const block = state.blocks[blockKey];
      if (!block || !block.paramsLoaded) return;
      const floats = new Array(block.params.length);
      for (const param of block.params) {
        const wireIndex = param.wireIndex === undefined ? param.index : param.wireIndex;
        floats[wireIndex] = paramValueToNormalized(param);
      }
      if (floats.every(Number.isFinite)) saveFxParamCache(blockKey, floats);
    }

function restoreFxParamCache(blockKey, block) {
      if (!block || block.model === 'None' || !block.params || !block.params.length) return false;
      const cached = readFxParamCache()[fxParamCacheKey(blockKey, block)];
      if (!cached || cached.model !== block.model || !Array.isArray(cached.floats) || cached.floats.length !== block.params.length || !cached.floats.every(Number.isFinite)) return false;

      applyFloatValuesToBlock(blockKey, cached.floats);
      block.paramsLoaded = true;
      block.paramsFromCache = true;
      block.paramsPreset = state.selectedPreset;
      block.cachedAt = Number(cached.savedAt) || 0;
      // Saved values are only shown: they never become the effect's Original (which writes every parameter) and never
      // count as known (fxValuesKnown), because the preset may have changed elsewhere since they were read.
      block.originalFloats = null;
      block.originalModel = null;
      block.originalPreset = null;
      log(block.title + ' is showing cached parameters last read for preset ' + state.selectedPreset + '.');
      return true;
    }

function holdFXRefreshQueueForLateReply(delayMs) {
      state.paramRefreshDiscardPending = true;
      if (state.paramRefreshDrainTimer) clearTimeout(state.paramRefreshDrainTimer);
      state.paramRefreshDrainTimer = setTimeout(() => {
        state.paramRefreshDiscardPending = false;
        state.paramRefreshDrainTimer = null;
        log('FX parameter reply drain finished.');
        requestNextFXParamRefresh();
      }, delayMs);
    }

function cancelFXParamRefresh() {
      state.paramRefreshQueue = [];
      const cancelledBlock = state.pendingParamBlock;
      state.pendingParamBlock = null;
      if (state.pendingParamTimer) clearTimeout(state.pendingParamTimer);
      state.pendingParamTimer = null;

      if (cancelledBlock) holdFXRefreshQueueForLateReply(1200);
    }

function queueFXParamRefreshes() {
      if (state.fileBusy) return;   // a preset export / import reads and writes the effects itself
      cancelFXParamRefresh();
      state.paramRefreshQueue = FX_BLOCK_KEYS.filter(key => {
        const block = state.blocks[key];
        return block && block.on && block.model !== 'None' && block.params && block.params.length > 0;
      });

      if (state.paramRefreshQueue.length === 0) {
        log('No active FX blocks to refresh.');
        return;
      }

      log('Refreshing FX parameters: ' + state.paramRefreshQueue.map(key => state.blocks[key].title).join(', '));
      requestNextFXParamRefresh();
    }

async function requestNextFXParamRefresh() {
      if (state.pendingParamBlock || state.paramRefreshDiscardPending) return;

      const blockKey = state.paramRefreshQueue.shift();
      if (!blockKey) return;

      const cfg = blockSlotConfig[blockKey];
      const block = state.blocks[blockKey];

      if (!cfg || !block) {
        requestNextFXParamRefresh();
        return;
      }

      state.pendingParamBlock = blockKey;

      if (state.pendingParamTimer) clearTimeout(state.pendingParamTimer);
      state.pendingParamTimer = setTimeout(() => {
        log('FX parameter refresh timed out for ' + block.title);
        state.pendingParamBlock = null;
        state.pendingParamTimer = null;
        holdFXRefreshQueueForLateReply(300);
        requestNextFXParamRefresh();
      }, 900);

      await writeC304(
        block.title + ' param refresh',
        new Uint8Array([0x08, 0xC0, 0x08, 0x03, 0x18, cfg.refreshSlot, 0x89, 0x00, 0x00, 0x00])
      );
    }

function isFXParamRefreshResponse(data) {
      return data.length >= 10 &&
        data[1] === 0xC0 &&
        data[2] === 0x08 &&
        data[3] === 0x06 &&
        data[4] === 0x22;
    }

function handleFXParamRefreshResponse(data) {
      resetMidiPickup();
      const blockKey = state.pendingParamBlock;

      if (!blockKey) {
        if (state.paramRefreshDiscardPending) {
          state.paramRefreshDiscardPending = false;
          if (state.paramRefreshDrainTimer) clearTimeout(state.paramRefreshDrainTimer);
          state.paramRefreshDrainTimer = null;
          log('Discarded a late FX parameter response while draining the previous request.');
          requestNextFXParamRefresh();
          return;
        }
        log('FX parameter response received with no pending block.');
        return;
      }

      const block = state.blocks[blockKey];
      const floatByteLength = data[5];
      const start = 6;
      const end = start + floatByteLength;

      if (!block || end > data.length) {
        log('Invalid FX parameter response for ' + blockKey + ': ' + hex(data));
        state.pendingParamBlock = null;
        requestNextFXParamRefresh();
        return;
      }

      const floats = decodeFloat32Array(data.slice(start, end));
      applyFloatValuesToBlock(blockKey, floats);
      const replaceOriginal = block.paramsFromCache || block.originalModel !== block.model || block.originalPreset !== state.selectedPreset;
      block.paramsLoaded = true;
      block.paramsFromCache = false;
      block.paramsPreset = state.selectedPreset;
      block.cachedAt = 0;
      saveFxParamCache(blockKey, floats);
      // ORIGINAL of the FX presets: the values as first read for this preset and model.
      if (replaceOriginal) {
        block.originalFloats = floats.slice();
        block.originalModel = block.model;
        block.originalPreset = state.selectedPreset;
        block.fxPresetActive = -1;
      }

      if (state.pendingParamTimer) clearTimeout(state.pendingParamTimer);
      state.pendingParamBlock = null;
      for (let i = fxValueWaiters.length - 1; i >= 0; i--) {
        if (fxValueWaiters[i].key === blockKey) fxValueWaiters.splice(i, 1)[0].resolve(true);
      }

      log(block.title + ' params loaded: ' + floats.map(x => x.toFixed(3)).join(', '));
      render();

      setTimeout(requestNextFXParamRefresh, 80);
    }

function decodeFloat32Array(bytes) {
      const out = [];
      const view = new DataView(new Uint8Array(bytes).buffer);

      for (let i = 0; i + 3 < bytes.length; i += 4) {
        out.push(view.getFloat32(i, true));
      }

      return out;
    }

function applyFloatValuesToBlock(blockKey, floats) {
      const block = state.blocks[blockKey];
      if (!block || !block.params) return;

      floats.forEach((normalized, index) => {
        const param = block.params.find(p => (p.wireIndex === undefined ? p.index : p.wireIndex) === index);
        if (!param) return;
        param.value = normalizedToParamValue(param, normalized);
      });
    }

function normalizedToParamValue(param, normalized) {
      const meta = param.meta || rangeMeta(0, 10, 0.1, '', 1);
      const n = clamp(Number(normalized), 0, 1);

      if (meta.kind === 'enum') {
        const maxIndex = Math.max(0, meta.options.length - 1);
        return Math.max(0, Math.min(maxIndex, Math.round(n * maxIndex)));
      }

      const scaled = meta.normalizedReversePower
        ? 1 - Math.pow(1 - n, meta.normalizedReversePower)
        : Math.pow(n, meta.normalizedPower || 1);
      return roundToStep(meta.min + (scaled * (meta.max - meta.min)), meta.step || 0.1);
    }

function parseSelectedCaptureState(payload) {
      const fields = parseProtoFields(payload);
      return {
        enabled: fields[1] && fields[1][0] ? fields[1][0].value : null,
        name: firstString(fields, 2),
        id: firstString(fields, 3)
      };
    }

function parseSelectedIRState(payload) {
      const fields = parseProtoFields(payload);
      return {
        enabled: fields[1] && fields[1][0] ? fields[1][0].value : null,
        shortName: firstString(fields, 2),
        fullName: firstString(fields, 3)
      };
    }

function isFEStreamPacket(data) {
      if (data.length < 3) return false;
      if (data[1] === 0xC0) return false; // complete single-packet message
      if (data[0] === 0xFE || data[0] === 0xFD || data[0] === 0xCE || data[0] === 0xD0) return true;

      if ((state.stateMode === 'metadata' || state.stateMode === 'current' || state.stateMode === 'library') && (data[1] & 0x80) === 0x80) return true;

      return false;
    }

function appendFEStreamPayload(data) {
      const payload = data.slice(2);
      for (const b of payload) state.feBytes.push(b);
    }

function parseCurrentPresetState(data) {
      state.protocol.lastStateSync = Date.now();
      log('CURRENT STATE CANDIDATE len=' + data.length + ': ' + hex(data));
    }

function scheduleFEParse() {
      if (state.feTimer) clearTimeout(state.feTimer);
      state.feTimer = setTimeout(parseBufferedFE, 4000);   // only if the last packet got lost
    }

function parseBufferedFE() {
      if (state.feBytes.length === 0) return;

      if (state.protocol.metadataLoaded) {
        log('FE metadata ignored: already loaded for this session.');
        state.feBytes = [];
        state.stateMode = 'idle';
        return;
      }

      const bytes = state.feBytes.slice();
      log('Parsing FE payload buffer: ' + bytes.length + ' bytes');
      const parsed = parseStructuredFE(bytes);

      state.captureNames = new Map();
      parsed.captures.forEach((capture, idx) => {
        const name = capture.name;
        if (name && !/^capture\s+\d+$/i.test(name)) {
          state.captureNames.set(idx + 1, name);
        }
      });

      state.presetNames = new Map();
      parsed.presets.forEach((preset, idx) => {
        state.presetNames.set(idx + 1, preset.name || 'Empty');
      });

      state.irNames = new Map();
      parsed.irs.forEach((ir, idx) => {
        const name = ir.shortName;
        if (name && !/^ir\s+\d+$/i.test(name)) {
          state.irNames.set(idx + 1, name);
        }
      });

      state.protocol.feSyncComplete = true;
      state.protocol.metadataLoaded = true;

      log('Structured FE parse: captures=' + parsed.captures.length + ', presets=' + parsed.presets.length + ', IRs=' + parsed.irs.length);
      log('Metadata locked for this session.');

      if (parsed.captures.length > 0) log('Capture sample: ' + parsed.captures.slice(0, 5).map(x => x.name).join(' | '));
      if (parsed.presets.length > 0) log('Preset sample: ' + parsed.presets.slice(0, 8).map(x => x.name || 'Empty').join(' | '));
      if (parsed.irs.length > 0) log('IR sample: ' + parsed.irs.map(x => x.shortName).join(' | '));

     renderPresetSelect();
      renderCaptureIR();

      state.feBytes = [];
      state.stateMode = 'idle';
    }

function parseStructuredFE(bytes) {
      const top = parseProtoFields(bytes);
      // Slot lists keep every record in place: list position = slot number, even if a name cannot be read.
      const captures = (top[17] || []).filter(entry => entry.wire === 2).map(entry => parseCaptureRecord(entry.raw)).slice(0, 25);
      const presets = (top[18] || []).filter(entry => entry.wire === 2).map(entry => parsePresetRecord(entry.raw)).filter(record => isValidPresetRecord(record)).slice(0, 64);
      while (presets.length < 64) presets.push({ name: '', captureName: '', captureID: '', irShortName: '', irFullName: '' });
      const irs = (top[19] || []).filter(entry => entry.wire === 2).map(entry => parseIRRecord(entry.raw)).slice(0, 5);
      return { captures, presets, irs };
    }

function parseCaptureRecord(payload) {
      const fields = parseProtoFields(payload);
      return { id: firstString(fields, 1), name: firstString(fields, 2), creator: nestedStrings(fields, 4).join(' / '), instrument: firstString(fields, 10) };
    }

function parsePresetRecord(payload) {
      const fields = parseProtoFields(payload);
      return { name: firstString(fields, 1), captureName: firstString(fields, 7), captureID: firstString(fields, 8), irShortName: firstString(fields, 9), irFullName: firstString(fields, 10) };
    }

function parseIRRecord(payload) {
      const fields = parseProtoFields(payload);
      return { shortName: firstString(fields, 1), fullName: firstString(fields, 3) };
    }

function isValidPresetRecord(record) {
      if (record.name === '') return true;
      if (record.name === null || record.name === undefined) return false;
      if (record.name.length > 120) return false;
      return true;
    }

function parseProtoFields(bytes) {
      const fields = {};
      let i = 0;
      while (i < bytes.length) {
        const tagInfo = readVarint(bytes, i);
        if (!tagInfo) break;
        const tag = tagInfo.value;
        const field = tag >> 3;
        const wire = tag & 0x07;
        i = tagInfo.next;
        if (!fields[field]) fields[field] = [];
        if (wire === 0) {
          const valueInfo = readVarint(bytes, i);
          if (!valueInfo) break;
          fields[field].push({ wire, raw: bytes.slice(i, valueInfo.next), value: valueInfo.value });
          i = valueInfo.next;
        } else if (wire === 1) {
          if (i + 8 > bytes.length) break;
          fields[field].push({ wire, raw: bytes.slice(i, i + 8) });
          i += 8;
        } else if (wire === 2) {
          const lenInfo = readVarint(bytes, i);
          if (!lenInfo) break;
          const start = lenInfo.next;
          const end = start + lenInfo.value;
          if (end > bytes.length) break;
          const raw = bytes.slice(start, end);
          fields[field].push({ wire, raw, text: decodePrintable(raw) });
          i = end;
        } else if (wire === 5) {
          if (i + 4 > bytes.length) break;
          fields[field].push({ wire, raw: bytes.slice(i, i + 4) });
          i += 4;
        } else {
          break;
        }
      }
      return fields;
    }

function firstString(fields, fieldNumber) {
      const entries = fields[fieldNumber] || [];
      for (const entry of entries) {
        if (entry.wire !== 2) continue;
        const text = decodeText(entry.raw);
        if (text !== null) return text;
      }
      return '';
    }

function nestedStrings(fields, fieldNumber) {
      const entries = fields[fieldNumber] || [];
      const out = [];
      for (const entry of entries) {
        if (entry.wire !== 2) continue;
        const nested = parseProtoFields(entry.raw);
        Object.keys(nested).forEach(key => {
          nested[key].forEach(item => {
            if (item.wire === 2) {
              const text = decodePrintable(item.raw);
              if (text) out.push(text);
            }
          });
        });
      }
      return out;
    }

function readVarint(bytes, offset) {
      let value = 0n;
      let shift = 0n;
      for (let i = offset; i < Math.min(bytes.length, offset + 10); i++) {
        const b = BigInt(bytes[i]);
        value |= (b & 0x7Fn) << shift;
        if ((b & 0x80n) === 0n) {
          return { value: value > BigInt(Number.MAX_SAFE_INTEGER) ? Number.MAX_SAFE_INTEGER : Number(value), next: i + 1 };
        }
        shift += 7n;
      }
      return null;
    }

const strictUtf8 = new TextDecoder('utf-8', { fatal: true });

function decodeText(bytes) {
      if (bytes.length === 0) return '';
      for (const b of bytes) if (b < 32 || b === 127) return null;
      try { return strictUtf8.decode(new Uint8Array(bytes)); } catch (e) { return null; }
    }

function decodePrintable(bytes) {
      if (bytes.length === 0) return '';
      for (const b of bytes) if (b < 32 || b > 126) return null;
      return new TextDecoder().decode(new Uint8Array(bytes));
    }

const MSG = {
      SetPresetSlotsRequest: 29,
      SetPresetSlotsResponse: 30,
      RetrievePresetCabinetSettingsLiteResponse: 96,
      RetrieveLibraryContentRequest: 76,
      RetrieveLibraryContentResponse: 77,
      SetCaptureSlotContentRequest: 80,
      SetCaptureSlotContentResponse: 81,
      SetCabinetSlotContentRequest: 78,
      SetCabinetSlotContentResponse: 79,
      TunerMode: 127,
      RetrieveExpAssignmentsRequest: 60,
      RetrieveExpAssignmentsResponse: 61,
      SaveExpAssignmentsRequest: 62,
      TunerMetering: 128,
      RetrieveSettingsRequest: 65,
      RetrieveSettingsResponse: 66,
      UpdateSettingsRequest: 67,
      UpdateSettingsResponse: 68,
      RenamePresetRequest: 111,
      RenamePresetResponse: 112,
      PresetDirtyStateChanged: 115,
      BypassControl: 31,
      // not the Nano's: the Nano Cortex Controller tells the editor which of its footswitches was pressed in looper mode
      ControllerSwitch: 0x4E430001
    };

const PRESET_SLOT_OTHER = 4;

function buildFrame(payload, type) {
      const frame = [0, 0xC0, ...payload, type & 0xFF, (type >> 8) & 0xFF, 0, 0];
      frame[0] = frame.length - 2;
      return new Uint8Array(frame);
    }

function frameType(data) {
      if (data.length < 6 || data[1] !== 0xC0) return null;
      const n = data.length;
      return (data[n - 4] | (data[n - 3] << 8) | (data[n - 2] << 16) | (data[n - 1] << 24)) >>> 0;
    }

function framePayloadFields(data) {
      return parseProtoFields(data.slice(2, data.length - 4));
    }

function encodeInt32(value) {
      if (value >= 0) return encodeVarint(value);
      let x = BigInt.asUintN(64, BigInt(value));
      const out = [];
      while (x > 0x7Fn) {
        out.push(Number(x & 0x7Fn) | 0x80);
        x >>= 7n;
      }
      out.push(Number(x));
      return out;
    }

function presetChangeFrame(presetIndex) {
      const slots = state.presetSlots;
      const slotIndex = [slots.a1, slots.b1, slots.a2, slots.b2].indexOf(presetIndex);
      const currentSlot = slotIndex === -1 ? PRESET_SLOT_OTHER : slotIndex;
      return buildFrame([
        0x18, 0x00,
        0x20, ...encodeVarint(presetIndex),
        0x28, ...encodeInt32(-1),
        0x30, ...encodeInt32(-1),
        0x38, ...encodeInt32(-1),
        0x40, ...encodeInt32(-1),
        0x48, currentSlot
      ], MSG.SetPresetSlotsRequest);
    }

const PRESET_CHANGE_ACK = buildFrame([0x20, 0x01], MSG.SetPresetSlotsResponse);

async function selectPreset(preset) {
      if (!state.connected) {
        log('Preset ' + preset + ' not sent: not connected.');
        renderPresetSelect();
        return;
      }

      state.selectedPreset = preset;
      state.capture.lastActiveSlot = null;
      state.cabIR.lastActiveSlot = null;
      clearLocalEdit();
      renderPresetSelect();

      await writeC304('Preset change ' + preset, presetChangeFrame(preset - 1));
      beginPresetLoad();
    }

function handleTypedMessage(data) {
      const type = frameType(data);

      if (type === MSG.SetPresetSlotsRequest) {
        // Preset changed on the device (footswitch, knob) - mirror the app: update,
        // acknowledge, then re-read the state.
        const fields = framePayloadFields(data);
        const value = (n, fallback) => fields[n] && fields[n][0] ? fields[n][0].value : fallback;
        state.selectedPreset = value(4, 0) + 1;
        state.presetSlots = { a1: value(5, 0), b1: value(6, 0), a2: value(7, 0), b2: value(8, 0) };
        clearLocalEdit();
        log('Device preset change: preset ' + state.selectedPreset);
        renderPresetSelect();
        writeC304('Preset change ack', PRESET_CHANGE_ACK);
        beginPresetLoad();
        return true;
      }

      if (type === MSG.BypassControl) {
        // The controller switched an effect (footswitch): BypassControl { 1: 1, 3: slot 4-8, 4: 0 = on }. The Nano's
        // own short type-31 messages carry no slot and are left alone.
        const fields = framePayloadFields(data);
        const value = n => fields[n] && fields[n][0] ? fields[n][0].value : 0;
        const key = FX_BLOCK_KEYS[value(3) - 4];
        if (value(1) !== 1 || !key) return false;
        const block = state.blocks[key], on = value(4) === 0;
        fxSwitch.switched[key] = on;
        log('Controller: ' + block.title + ' ' + (on ? 'on' : 'off'));
        if (block.on !== on) {
          block.on = on;
          render();
          if (on && !state.fileBusy) readAfterEnable(key);
        }
        return true;
      }

      if (type === MSG.SetPresetSlotsResponse) {
        const fields = framePayloadFields(data);
        const ok = fields[4] && fields[4][0] && fields[4][0].value === 1;
        log('Preset change ' + (ok ? 'confirmed' : 'FAILED') + ': ' + hex(data));
        return true;
      }

      if (type === MSG.RetrieveLibraryContentResponse) {
        parseLibraryContent(Array.from(data.slice(2)));
        return true;
      }

      if (type === MSG.RetrieveExpAssignmentsResponse) {
        parseExpAssignments(data);
        return true;
      }

      if (type === MSG.RetrieveSettingsResponse) {
        const fields = framePayloadFields(data);
        const channel = fields[8] && fields[8][0] ? fields[8][0].value : 1; // 1-16; omitted = default
        state.mc6.channel = clamp(channel || 1, 1, 16);
        log('Nano MIDI channel: ' + state.mc6.channel);
        // 17 usbReturnGain (float32, dB): how loud the computer's sound is mixed in; left out = 0 dB
        const usb = fields[17] && fields[17][0] && fields[17][0].wire === 5 ? new DataView(Uint8Array.from(fields[17][0].raw).buffer).getFloat32(0, true) : 0;
        state.usbReturnDb = Number.isFinite(usb) ? clamp(usb, -60, 12) : 0;
        // 15 muteIn1, 16 muteProcessingChain: the guitar input / output is muted (left out = not muted)
        state.inputMuted = Boolean(fields[15] && fields[15][0] && fields[15][0].value);
        state.outputMuted = Boolean(fields[16] && fields[16][0] && fields[16][0].value);
        settingsWaiters.splice(0).forEach(resolve => resolve(true));
        jamApplyGain();
        renderJam();
        renderMutes();
        if (!$('mc6Overlay').hidden) renderMc6Panel();
        return true;
      }

      if (type === MSG.UpdateSettingsResponse) {
        const fields = framePayloadFields(data);
        log('Settings update ' + (fields[3] && fields[3][0] && fields[3][0].value === 1 ? 'confirmed' : 'not confirmed'));
        return true;
      }

      if (type === MSG.SetCabinetSlotContentResponse) {
        handleCabinetSlotContentResponse(data);
        return true;
      }

      if (type === MSG.TunerMode) {
        // Tuner switched on/off on the device itself (footswitch).
        const fields = framePayloadFields(data);
        const on = Boolean(fields[4] && fields[4][0] && fields[4][0].value);
        if (fields[7] && fields[7][0]) state.tuner.muted = Boolean(fields[7][0].value);
        if (on && !state.tuner.open) openTuner(true);
        if (!on && state.tuner.open) closeTuner(false);
        return true;
      }

      if (type === MSG.SetCaptureSlotContentResponse) {
        handleCaptureSlotContentResponse(data);
        return true;
      }

      if (type === MSG.RenamePresetResponse) {
        const fields = framePayloadFields(data);
        const ok = fields[4] && fields[4][0] && fields[4][0].value === 1;
        log('Rename ' + (ok ? 'confirmed' : 'FAILED: ' + (firstString(fields, 5) || hex(data))));
        if (!ok) syncPresetNames();
        return true;
      }

      if (type === MSG.PresetDirtyStateChanged) {
        const fields = framePayloadFields(data);
        state.presetDirty = Boolean(fields[3] && fields[3][0] && fields[3][0].value);
        if (!state.presetDirty) clearLocalEdit();   // saved or loaded again on the Nano itself
        renderPresetSelect();
        return true;
      }

      return false;
    }

async function renamePresetTo(preset, entered) {
      const name = String(entered).trim();
      if (name.length < 4) return 'Preset name must have at least 4 characters.';
      const taken = Array.from(state.presetNames.entries()).some(([i, n]) => i !== preset && String(n).trim().toLowerCase() === name.toLowerCase());
      if (taken) return 'This preset name already exists.';

      const nameBytes = Array.from(new TextEncoder().encode(name));
      if (nameBytes.length > 64) return 'Preset name is too long.';

      // RenamePresetRequestMessage { 1: action=UPDATE, 3: presetIndex, 4: presetNewName }
      const sent = await writeC304('Rename preset ' + preset + ' to "' + name + '"', buildFrame([
        0x08, 0x01,
        0x18, ...encodeVarint(preset - 1),
        0x22, nameBytes.length, ...nameBytes
      ], MSG.RenamePresetRequest));
      if (!sent) return 'Rename failed: the Bluetooth write did not go through.';

      if (levelStore.marks[preset]) { levelStore.marks[preset].name = name; saveLevelStore(); }   // the levelled mark goes with the name
      state.presetNames.set(preset, name);
      renderPresetSelect();
      return null;
    }

function requestLibraryContent() {
      if (!state.connected) return;
      if (state.stateMode !== 'idle' || state.pendingParamBlock) {
        setTimeout(requestLibraryContent, 1000);
        return;
      }

      state.stateMode = 'library';
      state.libraryBytes = [];
      // { 3: includeFactoryCaptures, 4: includeFactoryImpulseResponses, 5: includeUserCaptures, 6: includeUserImpulseResponses }
      writeC304('Library content request', buildFrame([0x18, 0x01, 0x20, 0x01, 0x28, 0x01, 0x30, 0x01], MSG.RetrieveLibraryContentRequest));

      // Give up waiting if nothing arrives (opening the library browser asks again). Through the controller the first
      // packet comes only once the Nano has sent the whole reply (about 3.3 s for 27 KB) - after 4 s the reply was
      // taken for something else and lost.
      setTimeout(() => {
        if (state.stateMode !== 'library' || state.libraryBytes.length !== 0) return;
        state.stateMode = 'idle';
        log('Library content: no reply');
      }, state.viaController ? 15000 : 4000);
    }

function utf8(bytes) {
      return new TextDecoder().decode(new Uint8Array(bytes));
    }

function parseLibraryContent(bytes) {
      state.libraryTimer = null;
      if (state.stateMode === 'library') state.stateMode = 'idle';

      let body = bytes;
      const n = body.length;
      if (n >= 4 && body[n - 4] === MSG.RetrieveLibraryContentResponse && body[n - 3] === 0 && body[n - 2] === 0 && body[n - 1] === 0) {
        body = body.slice(0, n - 4);
      }

      const fields = parseProtoFields(body);
      const toList = fieldNumber => (fields[fieldNumber] || [])
        .filter(entry => entry.wire === 2)
        .map((entry, index) => {
          const record = parseProtoFields(entry.raw);
          const text = n => record[n] && record[n][0] && record[n][0].wire === 2 ? utf8(record[n][0].raw).trim() : '';
          const author = record[4] && record[4][0] && record[4][0].wire === 2 ? parseProtoFields(record[4][0].raw) : {};
          return {
            index,
            name: text(2),
            type: text(6) || 'default',
            tags: (record[7] || []).filter(t => t.wire === 2).map(t => utf8(t.raw).trim()).filter(Boolean),
            instrument: text(10),
            author: author[2] && author[2][0] ? utf8(author[2][0].raw).trim() : '',
            description: text(5),
            corrupted: Boolean(record[13] && record[13][0] && record[13][0].value)
          };
        })
        .filter(item => item.name && !item.corrupted);
      const toNameList = fieldNumber => (fields[fieldNumber] || [])
        .filter(entry => entry.wire === 2)
        .map((entry, index) => ({ index, name: utf8(entry.raw).trim() }))
        .filter(item => item.name);
      const alphabetical = list => list.sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' }));

      state.library = {
        factory: alphabetical(toList(3)),
        user: alphabetical(toList(5)),
        irFactory: alphabetical(toNameList(4)),
        irUser: alphabetical(toNameList(6)),
        loaded: true,
        requested: true
      };
      state.libraryBytes = [];
      log('Capture library: ' + state.library.factory.length + ' factory, ' + state.library.user.length + ' user captures');
      log('Cab/IR library: ' + state.library.irFactory.length + ' factory, ' + state.library.irUser.length + ' user IRs');
      renderShared();   // what each shared preset needs: on the Nano or not
      renderCaptureIR();
      if (!$('libraryOverlay').hidden) renderLibraryBrowser();
    }

async function loadLibraryCapture(kind, index) {
      const item = (kind === 'factory' ? state.library.factory : state.library.user).find(x => x.index === index);
      if (!item) { renderCaptureIR(); return null; }
      const slot = await chooseSlot('capture', item.name);
      if (!slot) { renderCaptureIR(); return null; }

      // SetCaptureSlotContentRequestMessage { 3: captureSlot (0-24),
      //   4: factory id { 1: index, 2: name } | 5: user id { 1: index, 2: name } }
      const nameBytes = Array.from(new TextEncoder().encode(item.name));
      const identifier = [0x08, ...encodeVarint(item.index), 0x12, ...encodeVarint(nameBytes.length), ...nameBytes];
      const frame = buildFrame([
        0x18, ...encodeVarint(slot - 1),
        kind === 'factory' ? 0x22 : 0x2A, ...encodeVarint(identifier.length), ...identifier
      ], MSG.SetCaptureSlotContentRequest);

      if (frame.length - 2 > 255) { toast('Capture name is too long.', 'error'); renderCaptureIR(); return null; }

      state.pendingSlotAssignment = { slot, name: item.name };
      await writeC304('Load library capture "' + item.name + '" into slot ' + slot, frame);
      if (!await waitUntil(() => sameName(state.captureNames.get(slot), item.name), 6000)) return null;
      if (!state.capture.on || state.capture.activeSlot !== slot) {
        await wait(400);   // the confirmatory state read of the loaded slot
        await setCapture(slot);
      }
      return slot;
    }

function handleCaptureSlotContentResponse(data) {
      const fields = framePayloadFields(data);
      const ok = fields[3] && fields[3][0] && fields[3][0].value === 1;
      const pending = state.pendingSlotAssignment;
      state.pendingSlotAssignment = null;

      if (!ok) {
        const message = fields[4] && fields[4][0] ? utf8(fields[4][0].raw) : hex(data);
        log('Loading library capture FAILED: ' + message);
        toast('The Nano refused to load the capture: ' + message, 'error', 6000);
        renderCaptureIR();
        return;
      }

      log('Library capture loaded' + (pending ? ': "' + pending.name + '" in slot ' + pending.slot : ''));
      if (pending) state.captureNames.set(pending.slot, pending.name);
      state.protocol.skipFXModelApply = true;
      setTimeout(requestCurrentPresetState, 300);
    }

const EXP_RANGES = [
      { key: 'gain', label: 'Gain', save: 4, icon: 'amp' },
      { key: 'bass', label: 'Bass', save: 5, icon: 'amp' },
      { key: 'mid', label: 'Mid', save: 6, icon: 'amp' },
      { key: 'treble', label: 'Treble', save: 7, icon: 'amp' },
      { key: 'level', label: 'Level (Capture Volume)', save: 13, icon: 'capture' },
      { key: 'gate', label: 'Input Gate Amount', save: 21, icon: 'gate' },
      { key: 'pre1', label: 'Pre FX 1 Amount', save: 8, block: 'pre1' },
      { key: 'pre2', label: 'Pre FX 2 Amount', save: 9, block: 'pre2' },
      { key: 'post1', label: 'Post FX 1 Amount', save: 10, block: 'post1' },
      { key: 'post2', label: 'Post FX 2 Amount', save: 11, block: 'post2' },
      { key: 'post3', label: 'Post FX 3 Amount', save: 12, block: 'post3' }
    ];

const EXP_BYPASS = [
      { key: 'capture', label: 'Capture', save: 14, icon: 'capture' },
      { key: 'cab', label: 'Cab / IR', save: 15, icon: 'cab' },
      { key: 'pre1', label: 'Pre FX 1', save: 16, block: 'pre1' },
      { key: 'pre2', label: 'Pre FX 2', save: 17, block: 'pre2' },
      { key: 'post1', label: 'Post FX 1', save: 18, block: 'post1' },
      { key: 'post2', label: 'Post FX 2', save: 19, block: 'post2' },
      { key: 'post3', label: 'Post FX 3', save: 20, block: 'post3' },
      { key: 'gate', label: 'Input Gate', save: 22, icon: 'gate' }
    ];

const EXP_MODES = [['heelToe', 'Heel-Toe'], ['switch', 'Switch'], ['stop', 'Stop']];

const rawToPct = raw => Math.round(clamp(raw, 0, 255) * 100 / 255);

const pctToRaw = pct => Math.round(clamp(pct, 0, 100) * 255 / 100);

const expAssignmentWaiters = [];

function defaultExpRange() { return { on: false, inverted: false, min: 0, max: 100 }; }

function defaultExpBypass() { return { on: false, mode: 'heelToe', inverted: false, delay: 600, latch: false }; }

function requestExpAssignments() {
      state.exp.preset = state.selectedPreset;
      state.exp.loaded = false;
      setExpStatus('Loading assignments…');
      renderExpPanel();
      state.exp.queue = state.exp.queue.filter(req => req.verify);
      const pending = state.exp.pending;
      if (!(pending && !pending.verify && pending.preset === state.exp.preset)) state.exp.queue.push({ preset: state.exp.preset });
      pumpExpRequests();
    }

function pumpExpRequests() {
      if (state.exp.pending || !state.exp.queue.length || !state.connected) return;
      const req = state.exp.queue.shift();
      const fail = reason => {
        if (state.exp.pending !== req) return;
        clearTimeout(req.timer);
        state.exp.pending = null;
        expRequestFailed(req, reason);
        pumpExpRequests();
      };
      state.exp.pending = req;
      req.timer = setTimeout(() => fail('no answer'), 5000);
      writeC304('Expression assignments ' + (req.verify ? 'check' : 'request') + ' (preset ' + req.preset + ')',
        buildFrame([0x08, 0x03, 0x18, ...encodeVarint(req.preset - 1)], MSG.RetrieveExpAssignmentsRequest))
        .then(ok => { if (!ok) fail('write failed'); });
    }

function expRequestFailed(req, reason) {
      log('Expression assignments ' + (req.verify ? 'check' : 'request') + ' for preset ' + req.preset + ': ' + reason);
      if (req.preset !== state.exp.preset) return;
      if (req.verify) { setExpStatus('Sent to preset ' + req.preset + ', but the check got no answer.'); return; }
      if (!state.exp.loaded) {
        setExpStatus('Preset ' + req.preset + ': the Nano did not send its assignments. Reopen to try again.');
        renderExpPanel();
        if (state.mc6.mixSlot >= 0) render();
      }
    }

function resetExpRequests() {
      if (state.exp.pending) clearTimeout(state.exp.pending.timer);
      state.exp.pending = null;
      state.exp.queue = [];
    }

    function setExpStatus() { /* replaced by pro/ui.js */ }

function decodeExpAssignments(data) {
      const fields = framePayloadFields(data);
      const nested = n => fields[n] && fields[n][0] && fields[n][0].wire === 2 ? parseProtoFields(fields[n][0].raw) : null;
      const num = (rec, n) => rec && rec[n] && rec[n][0] ? rec[n][0].value : 0;   // zero values are omitted
      const ranges = {}, bypass = {};

      EXP_RANGES.forEach(r => {
        const rec = nested(r.save - 1);
        ranges[r.key] = rec
          ? { on: true, inverted: Boolean(num(rec, 1)), min: rawToPct(num(rec, 2)), max: rawToPct(num(rec, 3)) }
          : defaultExpRange();
      });
      EXP_BYPASS.forEach(b => {
        const rec = nested(b.save - 1);
        const entry = defaultExpBypass();
        if (rec) {
          entry.on = true;
          const sub = n => rec[n] && rec[n][0] && rec[n][0].wire === 2 ? parseProtoFields(rec[n][0].raw) : null;
          if (sub(1)) { entry.mode = 'heelToe'; entry.inverted = Boolean(num(sub(1), 1)); entry.delay = num(sub(1), 2); }
          else if (sub(2)) { entry.mode = 'switch'; entry.inverted = Boolean(num(sub(2), 1)); entry.latch = Boolean(num(sub(2), 2)); }
          else if (sub(3)) { entry.mode = 'stop'; entry.delay = num(sub(3), 1); }
        }
        bypass[b.key] = entry;
      });
      return { ranges, bypass };
    }

function sameExpAssignments(a, b) {
      const rangeKey = v => v && v.on ? [v.inverted, pctToRaw(v.min), pctToRaw(v.max)].join() : 'off';
      const bypassKey = v => !v || !v.on ? 'off'
        : v.mode === 'switch' ? ['switch', v.inverted, v.latch].join()
        : v.mode === 'stop' ? ['stop', Math.round(v.delay)].join()
        : ['heelToe', v.inverted, Math.round(v.delay)].join();
      return EXP_RANGES.every(r => rangeKey(a.ranges[r.key]) === rangeKey(b.ranges[r.key])) &&
        EXP_BYPASS.every(t => bypassKey(a.bypass[t.key]) === bypassKey(b.bypass[t.key]));
    }

function parseExpAssignments(data) {
      const req = state.exp.pending;
      if (!req) { log('Expression assignments reply ignored: no request outstanding.'); return; }
      clearTimeout(req.timer);
      state.exp.pending = null;
      const decoded = decodeExpAssignments(data);

      if (req.verify) {
        const same = sameExpAssignments(decoded, req.verify);
        log('Expression assignments check for preset ' + req.preset + ': ' + (same ? 'matches' : 'DIFFERENT'));
        if (req.preset === state.exp.preset && !state.exp.saveTimer) {
          setExpStatus(same ? 'Saved to preset ' + req.preset + ' ✓' : 'Not confirmed: preset ' + req.preset + ' reports different assignments.');
        }
      } else if (req.preset !== state.exp.preset) {
        log('Expression assignments reply for preset ' + req.preset + ' dropped (now preset ' + state.exp.preset + ').');
      } else {
        state.exp.ranges = decoded.ranges;
        state.exp.bypass = decoded.bypass;
        state.exp.loaded = true;
        setExpStatus('Loaded from preset ' + state.exp.preset + '.');
        expAssignmentWaiters.slice().forEach(waiter => waiter());
        if (state.mc6.mixSlot >= 0) render();
        log('Expression assignments loaded: ' + EXP_RANGES.filter(r => state.exp.ranges[r.key].on).map(r => r.key)
          .concat(EXP_BYPASS.filter(b => state.exp.bypass[b.key].on).map(b => b.key + ' bypass')).join(', ') || 'none');
        renderExpPanel();
      }
      pumpExpRequests();
    }

function expSaveFrame() {
      const field = (n, bytes) => [...encodeVarint((n << 3) | 2), ...encodeVarint(bytes.length), ...bytes];
      const payload = [0x18, ...encodeVarint(state.exp.preset - 1)];
      EXP_RANGES.forEach(r => {
        const v = state.exp.ranges[r.key];
        if (!v || !v.on) return;
        payload.push(...field(r.save, [0x08, v.inverted ? 1 : 0, 0x10, ...encodeVarint(pctToRaw(v.min)), 0x18, ...encodeVarint(pctToRaw(v.max))]));
      });
      EXP_BYPASS.forEach(b => {
        const v = state.exp.bypass[b.key];
        if (!v || !v.on) return;
        const delay = encodeVarint(Math.round(clamp(v.delay, 0, 2000)));
        const inner = v.mode === 'switch' ? field(2, [0x08, v.inverted ? 1 : 0, 0x10, v.latch ? 1 : 0])
          : v.mode === 'stop' ? field(3, [0x08, ...delay])
          : field(1, [0x08, v.inverted ? 1 : 0, 0x10, ...delay]);
        payload.push(...field(b.save, inner));
      });
      return buildFrame(payload, MSG.SaveExpAssignmentsRequest);
    }

    function renderExpPanel() { /* replaced by pro/ui.js */ }

function closeExpPanel() {
      $('expOverlay').hidden = true;
    }

const CAPTURE_TYPES = [
      ['amp_head', 'Amp Head', 'cap-amp-head'],
      ['amp_combo', 'Combo', 'cap-amp-combo'],
      ['amp_and_cab', 'Amp + Cab', 'cap-amp-cab'],
      ['cab', 'Cab', 'cap-cab'],
      ['pedal', 'Pedal', 'cap-pedal'],
      ['overdrive', 'Overdrive', 'cap-overdrive'],
      ['fuzz', 'Fuzz', 'fuzz'],
      ['compressor', 'Compressor', 'compressor'],
      ['default', 'Other', 'capture']
    ];

function captureTypeInfo(type) {
      const entry = CAPTURE_TYPES.find(t => t[0] === type) || CAPTURE_TYPES[CAPTURE_TYPES.length - 1];
      return { key: entry[0], label: entry[1], icon: entry[2] };
    }

function escapeHTML(text) {
      return String(text).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    }

function capitalize(text) {
      return text ? text.charAt(0).toUpperCase() + text.slice(1) : text;
    }

function captureGroup(name) {
      return String(name || '').trim().split(/\s+/).slice(0, 2).join(' ');
    }

function libraryEntries() {
      return state.library.factory.map(item => ({ ...item, kind: 'factory' }))
        .concat(state.library.user.map(item => ({ ...item, kind: 'user' })))
        .map(item => ({ ...item, group: captureGroup(item.name), groupKey: captureGroup(item.name).toUpperCase() }))
        .sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: 'base' }));
    }

function filterLibrary(entries, skip = null) {
      const f = state.libBrowser;
      const q = f.q.trim().toLowerCase();
      return entries.filter(item =>
        (skip === 'source' || f.source === 'all' || item.kind === f.source) &&
        (skip === 'type' || f.type === 'all' || captureTypeInfo(item.type).key === f.type) &&
        (skip === 'instrument' || f.instrument === 'all' || item.instrument === f.instrument) &&
        (skip === 'tags' || !f.tags.size || f.tags.has(item.groupKey)) &&
        (!q || [item.name, item.author, item.instrument, item.description, ...item.tags].some(v => String(v).toLowerCase().includes(q)))
      );
    }

function renderChipRow(id, label, chips) {
      const row = $(id);
      row.innerHTML = '<span class="lib-row-label">' + label + '</span>';
      chips.forEach(chip => {
        const button = document.createElement('button');
        button.className = 'lib-chip' + (chip.active ? ' active' : '');
        button.innerHTML = (chip.icon ? '<span class="fx-icon" style="--block-color:' + (chip.active ? '#000' : '#f2f2f2') + ';--icon-ink:' + (chip.active ? '#fff' : '#000') + ';--icon: var(--ico-' + chip.icon + ')"></span>' : '') +
          escapeHTML(chip.text) + (chip.count !== undefined ? ' <span class="n">' + chip.count + '</span>' : '');
        button.addEventListener('click', chip.onClick);
        row.appendChild(button);
      });
    }

function renderLibraryBrowser() {
      const f = state.libBrowser;
      const entries = libraryEntries();
      const set = change => { Object.assign(f, change); renderLibraryBrowser(); };

      const bySource = filterLibrary(entries, 'source');
      renderChipRow('libSource', 'Source', [
        { text: 'All', count: bySource.length, active: f.source === 'all', onClick: () => set({ source: 'all' }) },
        { text: 'Factory', count: bySource.filter(i => i.kind === 'factory').length, active: f.source === 'factory', onClick: () => set({ source: 'factory' }) },
        { text: 'User', count: bySource.filter(i => i.kind === 'user').length, active: f.source === 'user', onClick: () => set({ source: 'user' }) }
      ]);

      const byType = filterLibrary(entries, 'type');
      renderChipRow('libTypes', 'Category', [{ text: 'All', count: byType.length, active: f.type === 'all', onClick: () => set({ type: 'all' }) }]
        .concat(CAPTURE_TYPES
          .map(([key, label, icon]) => ({ key, label, icon, count: byType.filter(i => captureTypeInfo(i.type).key === key).length }))
          .filter(t => t.count > 0 || f.type === t.key)
          .map(t => ({ text: t.label, icon: t.icon, count: t.count, active: f.type === t.key, onClick: () => set({ type: f.type === t.key ? 'all' : t.key }) }))));

      const byInstrument = filterLibrary(entries, 'instrument');
      const instruments = Array.from(new Set(entries.map(i => i.instrument).filter(Boolean))).sort();
      renderChipRow('libInstruments', 'Instrument', [{ text: 'All', count: byInstrument.length, active: f.instrument === 'all', onClick: () => set({ instrument: 'all' }) }]
        .concat(instruments.map(inst => ({ text: capitalize(inst), count: byInstrument.filter(i => i.instrument === inst).length, active: f.instrument === inst, onClick: () => set({ instrument: f.instrument === inst ? 'all' : inst }) }))));

      // The groups (first two words of the name) among the current results, alphabetically; several can be chosen
      // (either of them). The Nano's own tags are only searched, not shown.
      const groups = new Map();   // key -> { text, count }
      filterLibrary(entries, 'tags').forEach(item => {
        const group = groups.get(item.groupKey) || { text: item.group, count: 0 };
        group.count++;
        groups.set(item.groupKey, group);
      });
      entries.forEach(item => { if (f.tags.has(item.groupKey) && !groups.has(item.groupKey)) groups.set(item.groupKey, { text: item.group, count: 0 }); });
      const toggleTag = key => { if (f.tags.has(key)) f.tags.delete(key); else f.tags.add(key); renderLibraryBrowser(); };
      renderChipRow('libTags', 'Tags', groups.size
        ? Array.from(groups.entries()).sort((a, b) => a[1].text.localeCompare(b[1].text, undefined, { numeric: true, sensitivity: 'base' }))
          .map(([key, group]) => ({ text: group.text, count: group.count, active: f.tags.has(key), onClick: () => toggleTag(key) }))
        : [{ text: 'No tags', active: false, onClick: () => {} }]);

      const results = filterLibrary(entries);
      $('libCount').textContent = results.length + ' of ' + entries.length + ' captures' + (state.library.loaded ? '' : ' (loading…)');

      const list = $('libList');
      list.innerHTML = '';
      if (!results.length) {
        list.innerHTML = '<div class="lib-empty">' + (entries.length ? 'No captures match these filters.' : 'The library has not been loaded from the Nano yet.') + '</div>';
        return;
      }

      const currentName = String(state.currentCapture.name || '').trim().toLowerCase();
      let letter = null;
      results.forEach(item => {
        const first = item.name.charAt(0).toUpperCase();
        const heading = /[A-Z]/.test(first) ? first : '#';
        if (heading !== letter) {
          letter = heading;
          const h = document.createElement('div');
          h.className = 'lib-letter';
          h.textContent = heading;
          list.appendChild(h);
        }
        const type = captureTypeInfo(item.type);
        const meta = [item.author, capitalize(item.instrument), type.label, item.kind === 'user' ? 'User' : 'Factory'].filter(Boolean)
          .map(v => '<span>' + escapeHTML(v) + '</span>').join('<span>·</span>');
        const tagsHTML = '<span class="lib-tag' + (f.tags.has(item.groupKey) ? ' hit' : '') + '">' + escapeHTML(item.group) + '</span>';
        const row = document.createElement('button');
        row.className = 'lib-item' + (item.name.trim().toLowerCase() === currentName ? ' current' : '');
        row.title = item.description || item.name;
        row.innerHTML = '<span class="fx-icon" style="--icon: var(--ico-' + type.icon + ')"></span>' +
          '<span style="min-width:0"><div class="lib-name">' + escapeHTML(item.name) + '</div><div class="lib-meta">' + meta + tagsHTML + '</div></span>';
        row.addEventListener('click', () => {
          closeLibraryBrowser();
          loadLibraryCapture(item.kind, item.index);
        });
        list.appendChild(row);
      });
    }

function closeLibraryBrowser() {
      $('libraryOverlay').hidden = true;
    }

async function loadLibraryCab(kind, index) {
      const item = state.library[kind].find(x => x.index === index);
      if (!item) { renderCaptureIR(); return null; }

      const slot = await chooseSlot('cab', item.name);
      if (!slot) { renderCaptureIR(); return null; }

      const nameBytes = Array.from(new TextEncoder().encode(item.name));
      const identifier = [0x08, ...encodeVarint(item.index), 0x12, ...encodeVarint(nameBytes.length), ...nameBytes];
      const frame = buildFrame([
        0x18, ...encodeVarint(slot - 1),
        kind === 'irFactory' ? 0x22 : 0x2A, ...encodeVarint(identifier.length), ...identifier
      ], MSG.SetCabinetSlotContentRequest);

      if (frame.length - 2 > 255) { toast('Cab name is too long.', 'error'); renderCaptureIR(); return null; }

      state.pendingCabAssignment = { slot, name: item.name };
      await writeC304('Load library cab "' + item.name + '" into cab slot ' + slot, frame);
      return await waitUntil(() => sameName(state.irNames.get(slot), item.name), 6000) ? slot : null;
    }

state.slotUsage = null;

    function chooseSlot() { /* replaced by pro/ui.js */ }

function handleCabinetSlotContentResponse(data) {
      const fields = framePayloadFields(data);
      const ok = fields[3] && fields[3][0] && fields[3][0].value === 1;
      const pending = state.pendingCabAssignment;
      state.pendingCabAssignment = null;
      if (pending && pending.resolve) {   // the mic written into the slot before a save (storeCabMic)
        const message = ok ? '' : fields[4] && fields[4][0] ? utf8(fields[4][0].raw) : 'refused';
        log('Cab slot ' + pending.slot + (ok ? ' written' : ' NOT written: ' + message));
        pending.resolve({ ok, message });
        return;
      }

      if (!ok) {
        const message = fields[4] && fields[4][0] ? utf8(fields[4][0].raw) : hex(data);
        log('Loading library cab FAILED: ' + message);
        toast('The Nano refused to load the cab: ' + message, 'error', 6000);
        renderCaptureIR();
        return;
      }

      log('Library cab loaded' + (pending ? ': "' + pending.name + '" in cab slot ' + pending.slot : ''));
      if (!pending) return;
      state.irNames.set(pending.slot, pending.name);
      state.currentIR = { shortName: pending.name, fullName: pending.name, inBank: true, slot: pending.slot };
      selectCabIRSlot(pending.slot); // activate the slot, then re-read state and cab parameters
    }

function tunerModeFrame(on) {
      if (!on) return buildFrame([0x20, 0x00], MSG.TunerMode);
      // baseFrequency is a float32 field (wire type 5), not a double.
      return buildFrame([0x20, 0x01, 0x2D, ...float32LE(state.tuner.baseFrequency), 0x30, state.tuner.live ? 1 : 0, 0x38, state.tuner.muted ? 1 : 0], MSG.TunerMode);
    }

function openTuner(fromDevice = false) {
      state.tuner.open = true;
      state.tuner.live = !fromDevice;
      state.tuner.logged = 0;
      $('tunerOverlay').hidden = false;
      $('tunerFreq').value = String(state.tuner.baseFrequency);
      $('tunerMute').classList.toggle('on', state.tuner.muted);
      renderTunerReading(null);
      if (state.connected) writeC304('Tuner on (' + state.tuner.baseFrequency + ' Hz' + (fromDevice ? ', started on device' : '') + ')', tunerModeFrame(true));
    }

function closeTuner(send = true) {
      if (!state.tuner.open) return;
      state.tuner.open = false;
      $('tunerOverlay').hidden = true;
      if (send && state.connected) writeC304('Tuner off', tunerModeFrame(false));
    }

function handleTunerMetering(data) {
      if (!state.tuner.open) return;
      if (state.tuner.logged < 5) { state.tuner.logged++; log('RX tuner metering: ' + hex(data)); }
      const fields = framePayloadFields(data);
      const note = fields[4] && fields[4][0] ? utf8(fields[4][0].raw) : '';
      const dev = fields[5] && fields[5][0];
      let deviation = 0;
      if (dev && dev.raw.length === 8) deviation = new DataView(Uint8Array.from(dev.raw).buffer).getFloat64(0, true);
      if (dev && dev.raw.length === 4) deviation = new DataView(Uint8Array.from(dev.raw).buffer).getFloat32(0, true);
      const centered = Boolean(fields[7] && fields[7][0] && fields[7][0].value);
      renderTunerReading(note ? { note, deviation: Number.isFinite(deviation) ? deviation : 0, valid: true, centered } : null);
    }

    function renderTunerReading() { /* replaced by pro/ui.js */ }

function setTunerOption(change) {
      Object.assign(state.tuner, change);
      $('tunerMute').classList.toggle('on', state.tuner.muted);
      if (state.tuner.open && state.connected) writeC304('Tuner settings (' + state.tuner.baseFrequency + ' Hz' + (state.tuner.muted ? ', muted' : '') + ')', tunerModeFrame(true));
    }

function syncPresetNames() {
      state.protocol.metadataLoaded = false;
      syncMetadataAndState();
    }

async function refreshLists() { await syncMetadataAndState(); }

async function setCapture(slot) {
      if (!Number.isFinite(slot) || slot < 1 || slot > 25) return;
      const index = slot - 1;

      state.capture.selectedSlot = slot;
      state.capture.on = true;
      state.capture.lastActiveSlot = slot;

      await writeC304('08C0 capture change ' + slot, new Uint8Array([0x08, 0xC0, 0x18, 0x04, 0x20, index, 0x1C, 0x00, 0x00, 0x00]));

      renderCaptureIR();
      state.protocol.skipFXModelApply = true;
      setTimeout(requestCurrentPresetState, 300);
    }

function savePresetFrame(preset, name) {
      const nameBytes = Array.from(new TextEncoder().encode(name));
      return buildFrame([0x08, 0x01, 0x18, ...encodeVarint(preset - 1), 0x2A, nameBytes.length, ...nameBytes], 3);
    }

async function savePreset() {
      if (!state.connected) { showSaveResult('Not connected', 'error', 'Connect to the Nano first.'); return; }
      if (state.saveBusy) return;
      state.saveBusy = true;
      const preset = state.selectedPreset;
      showSaveResult('Saving…', '', 'Saving preset ' + preset);
      try {
        const name = state.presetNames.get(preset) || ('Preset ' + preset);
        const mic = await storeCabMic();   // a mic that was tried out goes into the cab slot first
        if (!state.connected) return;
        if (!await writeC304('save preset ' + preset, savePresetFrame(preset, name))) {
          showSaveResult('Save failed', 'error', 'The Bluetooth write failed: preset ' + preset + ' was not saved.');
          return;
        }
        await new Promise(r => setTimeout(r, 150));
        const checked = waitForPresetState(preset, 5000);
        requestCurrentPresetState();
        if (!await checked) { showSaveResult('Not confirmed', 'error', 'The Nano did not answer the check after saving preset ' + preset + '.'); return; }
        if (state.presetDirty) { showSaveResult('Not confirmed', 'error', 'The Nano still reports unsaved changes in preset ' + preset + '.'); return; }
        const micLeft = mic && mic.problem ? state.cabIR.micPending : null;
        clearLocalEdit();
        if (micLeft) { state.cabIR.micPending = micLeft; state.localEdit = true; }   // the mic is still to be saved: Save tries it again
        levelMarkCheck();   // a levelled mark of this preset counts from now on
        renderPresetSelect();
        if (mic && mic.problem) showSaveResult('Mic not saved', 'error', 'Preset ' + preset + ' is saved, but without the new mic: ' + mic.problem + '.');
        else showSaveResult('Saved ✓', 'ok', 'Preset ' + preset + ' saved and checked.' + (mic ? ' ' + mic.text : ''));
      } finally {
        state.saveBusy = false;
      }
    }

const copyDialog = { target: 0, busy: false };

function closeCopyPreset() {
      if (copyDialog.busy) return;
      $('copyOverlay').hidden = true;
    }

const settingsWaiters = [];

const MUTES = {
      in: { key: 'inputMuted', tag: 0x60, what: 'guitar input', end: 'IN', button: 'muteInBtn', label: 'muteInLabel',
        tip: 'Guitar input – click to mute it (the Nano\'s setting “Mute Guitar Input”)' },
      out: { key: 'outputMuted', tag: 0x68, what: 'guitar output', end: 'OUT', button: 'muteOutBtn', label: 'muteOutLabel',
        tip: 'Guitar output – click to mute it (the Nano\'s setting “Mute Guitar Output”: no guitar at the output jacks, the sound from USB stays)' }
    };

function requestSettings(tries = 40) {
      if (!state.connected) return;
      if (state.stateMode !== 'idle' && tries > 0) { setTimeout(() => requestSettings(tries - 1), 300); return; }   // not into a list that is being read
      writeC304('Retrieve settings', buildFrame([0x08, 0x03], MSG.RetrieveSettingsRequest));
    }

function renderMutes() {
      Object.values(MUTES).forEach(m => {
        const muted = state.connected && state[m.key] === true;
        $(m.button).hidden = !state.connected;
        $(m.button).classList.toggle('on', muted);
        $(m.label).textContent = (muted ? 'Unmute ' : 'Mute ') + m.what;
      });
      renderSignalChain();
    }

function renderMuteNode(node, which) {
      const m = MUTES[which], muted = state[m.key] === true;
      node.classList.add('sw');
      node.classList.toggle('muted', muted);
      node.title = muted ? 'The ' + m.what + ' is muted – click to bring it back' : m.tip;
      if (muted) node.insertAdjacentHTML('beforeend', '<span class="sc-lbl">Muted</span>');
      node.addEventListener('click', () => setMute(which, !muted));
    }

async function setMute(which, muted) {
      const m = MUTES[which];
      if (!state.connected || state.muteBusy) return;
      state.muteBusy = true;
      state[m.key] = muted;
      renderMutes();
      try {
        if (!await writeC304('Mute ' + m.what + (muted ? ' on' : ' off'), buildFrame([m.tag, muted ? 1 : 0], MSG.UpdateSettingsRequest))) {
          toast('The Bluetooth write failed: the ' + m.what + ' is ' + (muted ? 'not muted.' : 'still muted.'), 'error');
          state[m.key] = !muted;
          return;
        }
        // the check: the settings read back must say the same
        await new Promise(r => setTimeout(r, 350));
        const answered = new Promise(resolve => { settingsWaiters.push(resolve); setTimeout(() => resolve(false), 3000); });
        requestSettings();
        if (!await answered) toast('The Nano did not answer the check - listen whether the ' + m.what + ' is ' + (muted ? 'muted.' : 'back.'), 'error', 6000);
        else if (state[m.key] !== muted) toast('The Nano did not take it: the ' + m.what + ' is ' + (state[m.key] ? 'still muted.' : 'not muted.'), 'error', 6000);
        else toast(muted ? 'The ' + m.what + ' is muted - a click on ' + m.end + ' brings it back.' : 'The ' + m.what + ' is on again.', muted ? 'info' : 'ok');
      } finally {
        state.muteBusy = false;
        renderMutes();
      }
    }

    function showSaveResult() { /* replaced by pro/ui.js */ }

async function setGateEnabled(enabled) {
      const value = enabled ? 0x00 : 0x01;
      await writeC304(
        'Gate ' + (enabled ? 'ON' : 'OFF'),
        new Uint8Array([0x0A, 0xC0, 0x08, 0x01, 0x18, 0x09, 0x20, value, 0x1F, 0x00, 0x00, 0x00])
      );
    }

function encodeVarint(value) {
      const out = [];
      while (value > 0x7F) {
        out.push((value & 0x7F) | 0x80);
        value >>= 7;
      }
      out.push(value);
      return out;
    }

function captureDbToRaw(db) {
      const value = Math.max(-24, Math.min(12, Number(db)));

      if (value <= 0) {
        return Math.round(((value + 24) / 24) * 128);
      }

      return Math.round(128 + (value / 12) * 127);
    }

function captureRawToDb(raw) {
      raw = Math.max(0, Math.min(255, Number(raw)));

      if (raw <= 128) {
        return ((raw / 128) * 24) - 24;
      }

      return ((raw - 128) / 127) * 12;
    }

    function setCaptureVolumeUI() { /* replaced by pro/ui.js */ }

async function setCaptureVolumeDb(db) {
      const clampedDb = Math.max(-24, Math.min(12, Number(db)));
      state.captureVolumeDb = clampedDb;   // also what a preset export and the A/B compare read
      const raw = captureDbToRaw(clampedDb);
      const rawBytes = encodeVarint(raw);

      const payload = new Uint8Array([
        0x09 + rawBytes.length,
        0xC0,
        0x18, 0x0A,
        0x20, ...rawBytes,
        0x28, 0x00,
        0x1A, 0x00, 0x00, 0x00
      ]);

      await writeC304(
        'Capture volume ' + clampedDb.toFixed(1) + ' dB',
        payload,
        'capture-volume'
      );
    }

async function setGateReduction(percent) {
      const pct = Math.max(0, Math.min(100, Math.round(percent)));
      const encoded = pct + 108;
      const encodedBytes = encodeVarint(encoded);
      const payload = new Uint8Array([0x00, 0xC0, 0x18, 0x0B, 0x20, ...encodedBytes, 0x28, 0x00, 0x1A, 0x00, 0x00, 0x00]);
      payload[0] = payload.length - 2;
      await writeC304('Gate reduction ' + pct + '%', payload, 'gate-reduction');
    }

async function setFXModel(blockKey, modelName, readBack = true) {
      const cfg = blockSlotConfig[blockKey];
      const block = state.blocks[blockKey];
      const model = block ? block.models.find(m => m.name === modelName) : null;

      if (!cfg || !block) {
        log('No block config for ' + blockKey);
        return;
      }

      if (!model || !model.id) {
        log('No ' + cfg.label + ' model ID mapped for ' + modelName);
        return;
      }

      block.model = model.name;
      block.params = structuredClone(model.params);
      block.paramsLoaded = false;
      block.paramsFromCache = false;
      block.paramsPreset = state.selectedPreset;
      restoreFxParamCache(blockKey, block);
      render();

      const payload = new Uint8Array(
        [7 + model.id.length, 0xC0, 0x18, cfg.modelSlot, 0x20]
          .concat(model.id, [0x88, 0x00, 0x00, 0x00])
      );

      await writeC304(cfg.label + ' model select ' + model.name, payload);

      if (!readBack || !block.on) return;
      setTimeout(() => {
        state.paramRefreshQueue = [blockKey];
        state.pendingParamBlock = null;
        requestNextFXParamRefresh();
      }, 120);
    }

async function setFXBlockEnabled(blockKey, enabled) {
      const cfg = blockSlotConfig[blockKey];

      if (!cfg || cfg.enableSlot === null || cfg.enableSlot === undefined) {
        log((cfg ? cfg.label : blockKey) + ' toggle not wired yet');
        return;
      }

      const value = enabled ? 0x00 : 0x01;
      fxSwitch.switched[blockKey] = enabled;

      const sent = await writeC304(
        cfg.label + ' ' + (enabled ? 'ON' : 'OFF'),
        new Uint8Array([0x0A, 0xC0, 0x08, 0x01, 0x18, cfg.enableSlot, 0x20, value, 0x1F, 0x00, 0x00, 0x00])
      );
      if (enabled && sent && !state.fileBusy) readAfterEnable(blockKey);   // export / import read and write themselves
    }

const enableReadTimers = {};

function readAfterEnable(blockKey) {
      clearTimeout(enableReadTimers[blockKey]);
      enableReadTimers[blockKey] = setTimeout(() => {
        const block = state.blocks[blockKey];
        if (!state.connected || state.fileBusy || !block || !block.on || block.model === 'None') return;
        if (state.pendingParamBlock !== blockKey && !state.paramRefreshQueue.includes(blockKey)) state.paramRefreshQueue.push(blockKey);
        requestNextFXParamRefresh();
      }, 250);
    }

function float32LE(value) {
      const buf = new ArrayBuffer(4);
      new DataView(buf).setFloat32(0, value, true);
      return Array.from(new Uint8Array(buf));
    }

function readableValue(value, unit, decimals) {
      const v = Number(value), shown = Number(v.toFixed(decimals));   // (999.96 ms is "1.00 s", not "1000.0 ms")
      if (unit === 'Hz' && shown >= 1000) return (v / 1000).toFixed(v >= 9995 ? 1 : 2) + ' kHz';
      if (unit === 'ms' && shown >= 1000) return (v / 1000).toFixed(2) + ' s';
      return v.toFixed(decimals) + (unit ? ' ' + unit : '');
    }

function paramDisplayValue(param) {
      const meta = param.meta || rangeMeta(0, 10, 0.1, '', 1);

      if (meta.kind === 'enum') return meta.options[param.value] || meta.options[0] || '';
      const hz = eqView && eqView.frequencyText(param);   // a frequency of an EQ model: by the EQ view's scale
      if (hz) return hz;

      const decimals = meta.decimals === null || meta.decimals === undefined ? decimalsFromStep(meta.step || 0.1) : meta.decimals;
      return readableValue(param.value, meta.unit, decimals);
    }

function paramValueToNormalized(param) {
      const meta = param.meta || rangeMeta(0, 10, 0.1, '', 1);

      if (meta.kind === 'enum') {
        const maxIndex = Math.max(1, meta.options.length - 1);
        return clamp(param.value / maxIndex, 0, 1);
      }

      const normalized = clamp((Number(param.value) - meta.min) / (meta.max - meta.min), 0, 1);
      if (meta.normalizedReversePower) {
        return 1 - Math.pow(1 - normalized, 1 / meta.normalizedReversePower);
      }
      return Math.pow(normalized, 1 / (meta.normalizedPower || 1));
    }

async function setFXParam(blockKey, param, rawValue = null, fromPreset = false) {
      const cfg = blockSlotConfig[blockKey];
      if (!cfg) return;
      if (!fromPreset && state.blocks[blockKey]) state.blocks[blockKey].fxPresetActive = -1;   // changed by hand

      if (rawValue !== null && rawValue !== undefined) param.value = rawValue;

      const normalized = paramValueToNormalized(param);

      const payload = new Uint8Array([
        0x0F, 0xC0,
        0x08, 0x01,
        0x18, cfg.modelSlot,
        0x20, param.wireIndex === undefined ? param.index : param.wireIndex,
        0x2D,
        ...float32LE(normalized),
        0x63, 0x00, 0x00, 0x00
      ]);

      await writeC304(cfg.label + ' param ' + param.name + '=' + paramDisplayValue(param), payload, 'fx-param:' + blockKey + ':' + (param.wireIndex === undefined ? param.index : param.wireIndex));
      const block = state.blocks[blockKey];
      if (block && block.paramsLoaded) {   // this one value is now known; the rest of a saved set is still marked as saved
        block.paramsPreset = state.selectedPreset;
        saveCurrentFxParamCache(blockKey);
      }
    }

function coerceParamValue(param, rawValue) {
      const meta = param.meta || rangeMeta(0, 10, 0.1, '', 1);
      const value = Number(rawValue);

      if (Number.isNaN(value)) return null;

      if (meta.kind === 'enum') return Math.max(0, Math.min(meta.options.length - 1, Math.round(value)));
      return roundToStep(clamp(value, meta.min, meta.max), meta.step || 0.1);
    }

function sendParamValue(blockKey, param) {
      if (blockKey === 'gate') {
        setGateReduction(param.value);
        return;
      }

      if (FX_BLOCK_KEYS.includes(blockKey)) setFXParam(blockKey, param);
    }

function updateKnobVisual(knobEl, valueEl, normalized, text) {
      knobEl.style.setProperty('--pct', Math.round(normalized * 73) + '%');
      knobEl.style.setProperty('--angle', (-135 + normalized * 270) + 'deg');
      valueEl.textContent = text;
    }

    function askText() { /* replaced by pro/ui.js */ }

    function askConfirm() { /* replaced by pro/ui.js */ }

    function showNotice() { /* replaced by pro/ui.js */ }

    function toast() { /* replaced by pro/ui.js */ }

function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

function decimalsFromStep(step) {
      const s = String(step);
      return s.includes('.') ? s.split('.')[1].length : 0;
    }

function roundToStep(value, step) {
      if (!step) return value;
      const rounded = Math.round(value / step) * step;
      return Number(rounded.toFixed(decimalsFromStep(step)));
    }

function isParamDisabled(block, param) {
      if (!block || !param) return false;

      const name = normaliseName(param.name);

      if (name.includes('sync note')) {
        const sync = relatedSyncParam(block.params, param.name);
        return sync ? isSyncOff(sync) : false;
      }

      if (name === 'delay time' || name === 'delay time l' || name === 'delay time r' ||
          name === 'rate' || name === 'speed') {
        const sync = relatedSyncParam(block.params, param.name);
        return sync ? !isSyncOff(sync) : false;
      }

      return false;
    }

function relatedSyncParam(params, paramName) {
      const n = normaliseName(paramName);

      if (n.includes(' l')) {
        return params.find(p => normaliseName(p.name) === 'sync l') || params.find(p => normaliseName(p.name) === 'sync');
      }

      if (n.includes(' r')) {
        return params.find(p => normaliseName(p.name) === 'sync r') || params.find(p => normaliseName(p.name) === 'sync');
      }

      return params.find(p => normaliseName(p.name) === 'sync');
    }

function isSyncOff(syncParam) {
      if (!syncParam || !syncParam.meta || syncParam.meta.kind !== 'enum') return true;

      const label = String(syncParam.meta.options[syncParam.value] || '').toLowerCase();
      return label === 'off';
    }

