function isFactoryCabIR() {
      const full = String(state.currentIR.fullName || '');
      const short = String(state.currentIR.shortName || '');
      // the Nano names a factory IR "cab/mic/position"; the factory cabs are in its library; their mics it names
      if (/^[^/]+\/[^/]+\/\d+$/.test(full.trim())) return true;
      if (short && state.library.loaded && state.library.irFactory.some(item => sameName(item.name, short))) return true;
      if (short && state.cabIR.micsByCab[short.trim().toLowerCase()]) return true;
    
      const micNames = [
        'Condenser 184',
        'Condenser 414',
        'Dynamic 421',
        'Dynamic 57',
        'Ribbon 160'
      ];

      return micNames.some(mic =>
        full.includes('/' + mic + '/') ||
        full.includes(mic) ||
        short.includes('/' + mic + '/')
      );
    }

const CAB_RANGES = { level: [-96, 12, 0.1], highPass: [20, 800, 1, 1.68], lowPass: [1000, 20000, 1, 1.68] };

function closeMic() {
      $('micOverlay').hidden = true;
    }

function formatCabValue(key, value) {
      if (key === 'level') return (value > 0 ? '+' : '') + Number(value).toFixed(1) + ' dB';
      return readableValue(value, 'Hz', 0);
    }

const AMP_KNOBS = [
      { key: 'gain', label: 'Gain' },
      { key: 'bass', label: 'Bass' },
      { key: 'mid', label: 'Mid' },
      { key: 'treble', label: 'Treble' },
      { key: 'level', label: 'Level' }
    ];

const ampText = raw => (clamp(raw, 0, 255) / 25.5).toFixed(1);

function currentCaptureType() {
      const name = String(state.currentCapture.name || '').trim().toLowerCase();
      if (!name || !state.library || !state.library.loaded) return null;
      const item = state.library.factory.concat(state.library.user).find(x => String(x.name).trim().toLowerCase() === name);
      return item ? captureTypeInfo(item.type) : null;
    }

const AMP_WRITE_IDS = {
      gain: 0x00,
      level: 0x01,
      bass: 0x02,
      mid: 0x03,
      treble: 0x04
    };

async function setAmpKnob(key, rawValue) {
      const id = AMP_WRITE_IDS[key];

      if (id === undefined) {
        log('Amp ' + key + ' set to raw=' + rawValue + ' (write not yet confirmed -- not sent to device)');
        return;
      }

      const valueBytes = encodeVarint(clamp(Math.round(rawValue), 0, 255));
      const payload = new Uint8Array([0x00, 0xC0, 0x18, id, 0x20, ...valueBytes, 0x28, 0x00, 0x1A, 0x00, 0x00, 0x00]);
      payload[0] = payload.length - 2;

      await writeC304('Amp ' + key + ' = ' + rawValue, payload, 'amp:' + key);
    }

const FX_COLORS = {
      overdrive: '#FF7000',
      compressor: '#45F862',
      equalizer: '#0A74E0',
      filter: '#87DAFF',
      modulation: '#3500F1',
      delay: '#00FFDD',
      reverb: '#00FFDD',
      pitch: '#FFD236',
      utility: '#FFFFFF',
      none: '#5C5C5C'
    };

function fxStyle(model) {
      const name = String((model && model.name) || '');
      const category = String((model && model.category) || '');
      if (!model || name === 'None') return { color: FX_COLORS.none, icon: null };
      if (/comp|legendary 87/i.test(name)) return { color: FX_COLORS.compressor, icon: 'compressor' };
      if (/graphic|parametric|low-high cut/i.test(name)) return { color: FX_COLORS.equalizer, icon: 'equalizer' };
      if (/gate/i.test(name)) return { color: FX_COLORS.utility, icon: 'gate' };
      if (/doubler/i.test(name)) return { color: FX_COLORS.utility, icon: 'doubler' };
      if (/wah/i.test(name)) return { color: FX_COLORS.utility, icon: 'wah' };
      if (category === 'Wah/Filter') return { color: FX_COLORS.filter, icon: 'filter' };
      if (category === 'Overdrive') {
        return { color: FX_COLORS.overdrive, icon: /fuzz/i.test(name) ? 'fuzz' : /bass|b3k/i.test(name) ? 'bass-overdrive' : 'overdrive' };
      }
      if (category === 'Compressor') return { color: FX_COLORS.compressor, icon: 'compressor' };
      if (category === 'Modulation') return { color: FX_COLORS.modulation, icon: 'modulation' };
      if (category === 'Delay') return { color: FX_COLORS.delay, icon: 'delay' };
      if (category === 'Reverb') return { color: FX_COLORS.reverb, icon: 'reverb' };
      if (category === 'Pitch') return { color: FX_COLORS.pitch, icon: 'pitch' };
      return { color: FX_COLORS.utility, icon: 'utility' };
    }

function iconInk(color) {
      const [r, g, b] = [1, 3, 5].map(i => parseInt(color.slice(i, i + 2), 16) / 255);
      return 0.2126 * r + 0.7152 * g + 0.0722 * b < 0.3 ? '#fff' : '#000';
    }

const PRESET_FILE_FORMAT = 'nano-cortex-preset';

const PRESET_FILE_VERSION = 1;

const AMP_KEYS = ['gain', 'bass', 'mid', 'treble', 'level'];

const NL = String.fromCharCode(10);

const fxValueWaiters = [];

const wait = ms => new Promise(resolve => setTimeout(resolve, ms));

async function waitUntil(test, timeoutMs) {
      const end = Date.now() + timeoutMs;
      while (!test()) {
        if (Date.now() > end) return false;
        await wait(100);
      }
      return true;
    }

function sameName(a, b) {
      const x = String(a || '').trim().toLowerCase();
      return x !== '' && x === String(b || '').trim().toLowerCase();
    }

function fxValuesKnown(block) {
      return block.model === 'None' ||
        (!block.paramsFromCache && block.originalModel === block.model && block.originalPreset === state.selectedPreset) ||
        (block.importedModel === block.model && block.importedPreset === state.selectedPreset);
    }

function presetFileData() {
      const preset = state.selectedPreset;
      const round = (value, decimals) => Number(Number(value).toFixed(decimals));
      const fx = {};
      FX_BLOCK_KEYS.forEach(key => {
        const block = state.blocks[key];
        const entry = { model: block.model, on: block.model !== 'None' && Boolean(block.on) };
        if (block.model !== 'None' && fxValuesKnown(block)) {
          entry.values = block.params.map(param => round(paramValueToNormalized(param), 5));   // 0-1, by parameter
          entry.display = Object.fromEntries(block.params.map(param => [param.name, paramDisplayValue(param)]));
        }
        fx[key] = entry;
      });
      const data = {
        format: PRESET_FILE_FORMAT,
        version: PRESET_FILE_VERSION,
        editor: EDITOR_VERSION,
        exported: new Date().toISOString(),
        name: state.presetNames.get(preset) || 'Preset ' + preset,
        capture: { on: Boolean(state.capture.on), name: state.currentCapture.name || '', volumeDb: round(state.captureVolumeDb || 0, 1) },
        cab: { on: Boolean(state.cabIR.on), name: state.currentIR.shortName || '', fullName: state.currentIR.fullName || '' },
        amp: Object.fromEntries(AMP_KEYS.map(key => [key, state.amp[key]])),   // 0-255 as the Nano sends them
        gate: { on: Boolean(state.gate.on), reduction: state.gate.params[0] ? state.gate.params[0].value : 50 },
        fx
      };
      if (state.cabIR.paramsLoaded) {
        Object.assign(data.cab, {
          levelDb: round(state.cabIR.levelDb, 1),
          highPassHz: Math.round(state.cabIR.highPassHz),
          lowPassHz: Math.round(state.cabIR.lowPassHz)
        });
      }
      if (state.cabIR.on && isFactoryCabIR()) Object.assign(data.cab, { mic: state.cabIR.mic, position: state.cabIR.position });
      if (state.exp.loaded && state.exp.preset === preset) data.expression = structuredClone({ ranges: state.exp.ranges, bypass: state.exp.bypass });
      return data;
    }

async function findInLibrary(kinds, names) {
      if (!state.library.loaded) {
        requestLibraryContent();
        await waitUntil(() => state.library.loaded, 10000);
      }
      for (const kind of kinds) {
        const item = (state.library[kind] || []).find(x => names.some(name => sameName(x.name, name)));
        if (item) return { kind, index: item.index };
      }
      return null;
    }

const shared = { items: null, loading: false, error: '', at: 0, q: '' };

function captureSourceText(capture) {
      if (!capture) return '';
      if (capture.source === 'factory') return 'Factory capture – comes with the Nano';
      if (capture.source === 'cloud') return 'Cortex Cloud' + (capture.author ? ' – by ' + capture.author : '');
      return '';
    }

const cabText = cab => !cab || cab.on === false || !cab.name ? 'None – bypassed' :
      cab.name + (cab.mic ? ' · ' + cab.mic + (cab.position ? ', position ' + cab.position : '') : '');

const sharedSlotName = slot => Math.floor((slot - 1) / 5) + 1 + '-' + ((slot - 1) % 5 + 1);

function sharedCaptureState(capture) {
      if (!capture || capture.on === false || !capture.name) return { kind: 'none', text: 'None – the capture is bypassed' };
      if (!state.connected) return { kind: 'unknown', text: 'Connect the Nano to see whether you have it' };
      for (let slot = 1; slot <= 25; slot++) {
        if (sameName(state.captureNames.get(slot), capture.name)) return { kind: 'ok', text: '✓ On your Nano – slot ' + sharedSlotName(slot) };
      }
      if (!state.library.loaded) return { kind: 'unknown', text: 'Looking in your Nano’s library …' };
      if (state.library.factory.concat(state.library.user).some(item => sameName(item.name, capture.name))) {
        return { kind: 'load', text: 'In your Nano’s library – the import puts it into a slot' };
      }
      return { kind: 'missing', text: 'Missing on your Nano' };
    }

function sharedCabState(cab) {
      if (!cab || cab.on === false || !cab.name || !state.connected) return null;
      const names = [cab.name, cab.fullName].filter(Boolean);
      for (let slot = 1; slot <= 5; slot++) {
        if (names.some(name => sameName(state.irNames.get(slot), name))) return { kind: 'ok', text: '✓ On your Nano – cab slot ' + slot };
      }
      if (!state.library.loaded) return null;
      if (state.library.irFactory.concat(state.library.irUser).some(item => names.some(name => sameName(item.name, name)))) {
        return { kind: 'load', text: 'In your Nano’s library – the import puts it into a slot' };
      }
      return { kind: 'missing', text: 'Missing on your Nano' };
    }

function sharedCard(item) {
      const d = item.data, capture = d.capture || {}, cab = d.cab || {};
      const cs = sharedCaptureState(capture), ks = sharedCabState(cab);
      const date = item.created ? new Date(item.created).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) : '';
      const source = item.source || captureSourceText(capture);
      const captureName = capture.name || item.captureText;
      const fx = FX_BLOCK_KEYS.map(key => {
        const f = d.fx && d.fx[key];
        if (!f || !f.model || f.model === 'None') return '';
        const model = state.blocks[key].models.find(m => m.name === f.model);
        const color = model ? fxStyle(model).color : '#9aa0a6';
        return '<span class="' + (f.on ? '' : 'off') + '" style="--c:' + color + '" title="' + escapeHTML(state.blocks[key].title + (f.on ? '' : ' – off')) + '"><i></i>' +
          escapeHTML(f.model) + '</span>';
      }).join('');
      const captureCell = cs.kind === 'none' ? '<span class="src">' + escapeHTML(cs.text) + '</span>' :
        '<strong>' + escapeHTML(captureName) + '</strong>' +
        (cs.kind === 'missing' ? '<button class="shared-copy" data-act="copy" data-name="' + escapeHTML(captureName) + '" title="Copy the exact name">Copy name</button>' : '') +
        (source ? '<span class="src">' + escapeHTML(source) + '</span>' : '') +
        '<span class="shared-state ' + cs.kind + '">' + escapeHTML(cs.text) + '</span>';
      const cabCell = cab.on === false || !cab.name ? '<span class="src">None – bypassed</span>' :
        '<strong>' + escapeHTML(cabText(cab)) + '</strong>' + (ks ? '<span class="shared-state ' + ks.kind + '">' + escapeHTML(ks.text) + '</span>' : '');
      return '<article class="shared-card">' +
        '<div class="shared-top"><h3>' + escapeHTML(item.name) + '</h3><div class="shared-by">' +
          escapeHTML([item.user ? 'by ' + item.user : '', date].filter(Boolean).join(' · ')) + '</div></div>' +
        (item.description ? '<div class="shared-desc">' + escapeHTML(item.description) + '</div>' : '') +
        '<div class="shared-need"><span class="k">Capture</span><span class="v">' + captureCell + '</span>' +
          '<span class="k">Cab</span><span class="v">' + cabCell + '</span>' +
          (item.instrument ? '<span class="k">Played</span><span class="v">' + escapeHTML(item.instrument) + '</span>' : '') + '</div>' +
        (fx ? '<div class="shared-fx">' + fx + '</div>' : '') +
        '<div class="shared-actions"><span class="likes">' + (item.likes ? '👍 ' + item.likes : '') + '</span>' +
          (item.url ? '<button data-act="github" data-n="' + item.number + '" title="The preset on GitHub – questions, comments and 👍 go there">On GitHub</button>' : '') +
          '<button class="primary" data-act="import" data-n="' + item.number + '"' + (state.connected ? '' : ' disabled') + ' title="' +
            (state.connected ? 'Load it into the preset that is loaded now – nothing is stored until you press Save' : 'Connect to the Nano first') +
            '">Load into preset ' + state.selectedPreset + '</button></div>' +
        '</article>';
    }

function renderShared() {
      if ($('sharedOverlay').hidden) return;
      const list = $('sharedList'), count = $('sharedCount');
      const q = shared.q.trim().toLowerCase();
      const items = (shared.items || []).filter(item => !q || [item.name, item.description, item.captureText, item.source, item.instrument, item.user,
        item.data.capture && item.data.capture.name, item.data.cab && item.data.cab.name,
        ...FX_BLOCK_KEYS.map(key => item.data.fx && item.data.fx[key] && item.data.fx[key].model)].join(' ').toLowerCase().includes(q));
      $('sharedRefresh').disabled = shared.loading;
      if (shared.loading) count.textContent = 'Loading the shared presets from GitHub …';
      else if (shared.error) count.textContent = shared.error;
      else if (shared.items) count.textContent = items.length + (q ? ' of ' + shared.items.length : '') + ' shared preset' + (shared.items.length === 1 ? '' : 's') +
        ' – what each needs is checked against your Nano' + (state.connected ? '.' : ' once it is connected.');
      if (!shared.items) { list.innerHTML = shared.error ? '<div class="lib-empty">' + escapeHTML(shared.error) + '</div>' : ''; return; }
      list.innerHTML = items.length ? items.map(sharedCard).join('') :
        '<div class="lib-empty">' + (q ? 'No shared preset fits “' + escapeHTML(shared.q.trim()) + '”.' :
          'No presets are shared yet – be the first: “Share this preset”.') + '</div>';
    }

const AB_KEY_HINT = ' (A)';

function abSnapshot() {
      const data = presetFileData();
      delete data.expression;   // the expression assignments are stored at once: not part of the compare
      delete data.exported;
      delete data.name;
      return data;
    }

function abDiffers() {
      const ab = state.ab;
      if (!ab.active) return false;
      const other = ab.side === 'A' ? ab.B : ab.A;
      return JSON.stringify(abSnapshot()) !== JSON.stringify(other);
    }

function renderAb() {
      const ab = state.ab;
      if (ab.active && (!state.connected || ab.preset !== state.selectedPreset)) abEnd(true);
      $('abBox').classList.toggle('active', ab.active);
      $('abBox').classList.toggle('busy', ab.busy);
      const differs = !ab.busy && abDiffers();
      ['A', 'B'].forEach(side => {
        const seg = $('ab' + side);
        seg.classList.toggle('on', ab.active && ab.side === side);
        seg.classList.toggle('differs', differs);
        seg.title = !ab.active ? 'A/B compare: remember the settings as they are now as A, change things, then switch between A and the new settings' + AB_KEY_HINT
          : ab.side === side ? 'You hear ' + side + (side === 'A' ? ' (as remembered – changes you make now belong to A)' : ' (your changes)')
          : 'Switch to ' + side + (differs ? '' : ' – no difference yet') + AB_KEY_HINT;
      });
      $('abEnd').hidden = !ab.active;
    }

function abEnd(silent) {
      const ab = state.ab;
      if (!ab.active) return;
      ab.active = false;
      ab.A = ab.B = null;
      if (!silent) renderAb();
    }

const closeFootswitches = () => { $('fsOverlay').hidden = true; };

const LEVEL_STORE = 'nanoCortexLevel';

const AL_KINDS = [
      { key: 'clean', label: 'Clean' },
      { key: 'edge', label: 'Edge' },
      { key: 'drive', label: 'Drive' },
      { key: 'fuzz', label: 'Fuzz' },
      { key: 'lead', label: 'Lead' }
    ];

const AL_BASE = -20;

const AL_STEPS = { edge: 1.5, drive: 3, fuzz: 3, lead: 3 };

const AL_CORRECTION = {   // dB each sound needs against Clean to sound as loud at equal LUFS (model of the LUFS Meter)
      quiet: { clean: 0, edge: -0.5, drive: -2, fuzz: -1, lead: -2 },
      rehearsal: { clean: 0, edge: -0.5, drive: -0.5, fuzz: -0.5, lead: -0.5 }
    };

const AL_PROFILES = {
      quiet: { label: 'Quiet', text: 'Quiet – at home, about 60–75 dB at your ears. At low volume the ear hears little bass, so the mid-heavy sounds seem louder than their LUFS: Drive and Lead get 2 dB less, Fuzz 1 dB, Edge 0.5 dB less than their steps say.' },
      rehearsal: { label: 'Rehearsal', text: 'Rehearsal – with the band, about 95–105 dB at your ears. The ear is flatter at high volume: Edge, Drive, Fuzz and Lead get only 0.5 dB less than their steps say.' }
    };

const AL_SECONDS = 4;

const AL_PLAY_LUFS = -50;

const AL_CEILING_DB = -1;

const METER_FLOOR_DB = -60;

const NANO_AUDIO = /nano\s*cortex|neural\s*dsp/i;

const levelStore = { input: '', pairs: {}, kind: 'clean', profile: 'rehearsal', base: AL_BASE, steps: { ...AL_STEPS }, marks: {} };

const alIntent = kind => (kind === 'clean' ? 0 : kind === 'lead' ? levelStore.steps.drive + levelStore.steps.lead : levelStore.steps[kind]);

const alTarget = (kind = levelStore.kind) => Math.round((levelStore.base + alIntent(kind) + AL_CORRECTION[levelStore.profile][kind]) * 10) / 10;

function saveLevelStore() {
      try { localStorage.setItem(LEVEL_STORE, JSON.stringify(levelStore)); } catch (e) { /* storage unavailable */ }
    }

const nativeMeter = () => window.nanoMeter || null;

const meter = { on: false, starting: false, userOff: false, native: false, rate: 48000, ctx: null, stream: null, raw: [], weighted: [], buf: null,
      timer: null, lastTime: 0, channels: 2, total: 2, first: 1, label: '', deviceId: '', inputs: [], error: '',
      peakDb: [-Infinity, -Infinity], holdDb: [-Infinity, -Infinity], holdAt: [0, 0], clipAt: 0, energy: 0, frames: 0, blockPeak: 0, blocks: [] };

const autoLevel = { running: false, preparing: false, apply: true, kind: 'clean', preset: 0, blocks: [], played: 0, peak: 0, startedAt: 0,
      before: null, undo: null, last: null, levelAsk: 0, text: '', error: false };

const toDb = amplitude => (amplitude > 0 ? 20 * Math.log10(amplitude) : -Infinity);

const lufsOf = energy => (energy > 0 ? -0.691 + 10 * Math.log10(energy) : -Infinity);

const WEB_K_GAIN = Math.pow(10, 0.041 / 10);

const dbText = (db, signed = false) => {
      if (!Number.isFinite(db)) return '–';
      const value = Math.abs(db) < 0.05 ? 0 : db;
      return (signed && value > 0 ? '+' : '') + value.toFixed(1).replace('-', '−');
    };

const meterPos = db => (clamp((db - METER_FLOOR_DB) / -METER_FLOOR_DB, 0, 1) * 100).toFixed(1) + '%';

function blockEnergy(blocks) {
      const seconds = blocks.reduce((sum, b) => sum + b.s, 0);
      return seconds > 0 ? blocks.reduce((sum, b) => sum + b.e * b.s, 0) / seconds : 0;
    }

function gatedLoudness(blocks) {
      const windows = blocks.map((b, i) => blockEnergy(blocks.slice(Math.max(0, i - 3), i + 1)));
      const mean = list => list.reduce((a, b) => a + b, 0) / list.length;
      let kept = windows.filter(e => lufsOf(e) > -70);
      if (!kept.length) return -Infinity;
      const gate = lufsOf(mean(kept)) - 10;
      kept = kept.filter(e => lufsOf(e) > gate);
      return lufsOf(mean(kept));
    }

async function meterInputs() {
      const all = (await navigator.mediaDevices.enumerateDevices()).filter(d => d.kind === 'audioinput' && d.label);
      const real = all.filter(d => d.deviceId !== 'default' && d.deviceId !== 'communications');
      return real.length ? real : all;
    }

function meterPair(label, total) {
      const stored = Number(levelStore.pairs[label]);
      if (stored >= 1 && stored <= total && stored % 2 === 1) return stored;
      return NANO_AUDIO.test(label) && total >= 4 ? 3 : 1;
    }

const pairText = (first, total) => (first < total ? first + '/' + (first + 1) : String(first));

const meterIsDry = () => meter.on && NANO_AUDIO.test(meter.label) && meter.first < 3;

const METER_DENIED = 'The audio input was not allowed. Allow the microphone for the editor – in the browser at the lock symbol in the address bar, ' +
      'in the Mac app under System Settings > Privacy & Security > Microphone.';

async function meterStart(deviceId) {
      const m = meter;
      if (m.starting) return false;
      if (!nativeMeter() && !(navigator.mediaDevices && navigator.mediaDevices.getUserMedia)) {
        m.error = 'This browser gives the editor no audio input.';
        renderLevel();
        return false;
      }
      m.starting = true;
      m.error = '';
      renderLevel();
      try {
        m.error = (await (nativeMeter() ? meterStartNative(deviceId) : meterStartWeb(deviceId))) || '';
      } catch (err) {
        const name = err && err.name;
        m.error = name === 'NotAllowedError' || name === 'SecurityError' ? METER_DENIED
          : name === 'NotFoundError' || name === 'OverconstrainedError' ? 'This audio input is not there (any more).'
          : 'The audio input did not open: ' + ((err && err.message) || err);
      } finally {
        m.starting = false;
      }
      if (m.error) log('Output meter: ' + m.error);
      else {
        log('Output meter on: ' + m.label + ', channel' + (m.channels > 1 ? 's ' : ' ') + pairText(m.first, m.total) + ' of ' + m.total + ', ' +
          m.rate + ' Hz' + (m.native ? ' (helper of the Mac app)' : ''));
      }
      renderLevel();
      renderSignalChain();
      return !m.error;
    }

async function meterStartNative(deviceId) {
      const m = meter;
      const listed = await nativeMeter().list();
      if (listed.error) return listed.error;
      m.inputs = listed.devices.map(d => ({ deviceId: d.uid, label: d.name, channels: d.channels, standard: d.default }));
      const device = deviceId ? m.inputs.find(d => d.deviceId === deviceId)
        : m.inputs.find(d => d.label === levelStore.input) || m.inputs.find(d => NANO_AUDIO.test(d.label)) || m.inputs.find(d => d.standard) || m.inputs[0];
      if (!device) return deviceId ? 'This audio input is not there (any more).' : 'This Mac has no audio input.';
      meterStop();
      const reply = await nativeMeter().start({ uid: device.deviceId, first: meterPair(device.label, device.channels) });
      if (reply.error) return reply.error === 'denied' ? METER_DENIED : reply.error;
      Object.assign(m, { on: true, native: true, userOff: false, rate: reply.rate, total: reply.channels, first: reply.first, channels: reply.count,
        label: reply.name || device.label, deviceId: device.deviceId });
      nativeMeter().onData(data => {
        if (!m.on || !m.native) return;
        if (data.error) {
          meterStop();
          m.error = data.error;
          renderLevel();
          renderSignalChain();
        } else if (Array.isArray(data.p)) {
          meterFeed(data.p, Number(data.e) || 0, Number(data.n) || 0, m.rate);
        }
      });
      return '';
    }

async function meterStartWeb(deviceId) {
      const m = meter;
      let stream = null;
      try {
        const open = id => navigator.mediaDevices.getUserMedia({ audio: Object.assign(
          { echoCancellation: false, noiseSuppression: false, autoGainControl: false, channelCount: { ideal: 8 } }, id ? { deviceId: { exact: id } } : {}) });
        stream = await open(deviceId);
        m.inputs = await meterInputs();   // the names are readable once an input was allowed
        if (!deviceId) {
          const wanted = m.inputs.find(d => d.label === levelStore.input) || m.inputs.find(d => NANO_AUDIO.test(d.label));
          if (wanted && wanted.deviceId !== stream.getAudioTracks()[0].getSettings().deviceId) {
            stream.getTracks().forEach(track => track.stop());
            stream = await open(wanted.deviceId);
          }
        }
        meterStop();
        const track = stream.getAudioTracks()[0];
        const settings = track.getSettings();
        const label = track.label || 'Audio input';
        const total = Math.max(1, Math.min(32, Number(settings.channelCount) || 2));
        const first = meterPair(label, total);
        const ctx = new (window.AudioContext || window.webkitAudioContext)();
        const source = ctx.createMediaStreamSource(stream);
        const splitter = ctx.createChannelSplitter(Math.max(2, total));
        const sink = ctx.createGain();   // silent: only keeps the measuring nodes running in every browser
        sink.gain.value = 0;
        sink.connect(ctx.destination);
        source.connect(splitter);
        m.channels = first < total ? 2 : 1;
        for (let ch = 0; ch < m.channels; ch++) {
          const raw = ctx.createAnalyser();
          raw.fftSize = 8192;
          splitter.connect(raw, first - 1 + ch);
          raw.connect(sink);
          // K-weighting with the browser's own filters, fitted to the BS.1770 curve (within 0.05 dB from 30 Hz to 12 kHz
          // at any sample rate): high shelf +4 dB, then a high pass at 38 Hz with Q 0.5 (Web Audio takes that Q in dB).
          const shelf = ctx.createBiquadFilter();
          shelf.type = 'highshelf';
          shelf.frequency.value = 1500;
          shelf.gain.value = 4;
          const highPass = ctx.createBiquadFilter();
          highPass.type = 'highpass';
          highPass.frequency.value = 38.4;
          highPass.Q.value = -5.9;
          const weighted = ctx.createAnalyser();
          weighted.fftSize = 8192;
          splitter.connect(shelf, first - 1 + ch);
          shelf.connect(highPass);
          highPass.connect(weighted);
          weighted.connect(sink);
          m.raw.push(raw);
          m.weighted.push(weighted);
        }
        if (ctx.state === 'suspended') await ctx.resume();
        Object.assign(m, { on: true, native: false, userOff: false, ctx, stream, buf: new Float32Array(8192), lastTime: ctx.currentTime, rate: ctx.sampleRate,
          total, first, label, deviceId: settings.deviceId || deviceId || '' });
        track.addEventListener('ended', () => {
          if (m.stream !== stream) return;
          meterStop();
          m.error = 'The audio input is gone (USB cable?).';
          renderLevel();
          renderSignalChain();
        });
        m.timer = setInterval(meterTick, 25);
        return '';
      } catch (err) {
        if (stream) stream.getTracks().forEach(track => track.stop());
        throw err;
      }
    }

function meterStop() {
      const m = meter;
      autoLevelCancel('');
      clearInterval(m.timer);
      if (m.native && nativeMeter()) nativeMeter().stop();
      if (m.stream) m.stream.getTracks().forEach(track => track.stop());
      if (m.ctx) m.ctx.close().catch(() => {});
      Object.assign(m, { on: false, native: false, ctx: null, stream: null, raw: [], weighted: [], timer: null, peakDb: [-Infinity, -Infinity],
        holdDb: [-Infinity, -Infinity], clipAt: 0, energy: 0, frames: 0, blockPeak: 0, blocks: [] });
    }

function meterTick() {
      const m = meter;
      if (!m.on || m.native) return;
      const size = m.buf.length;
      const time = m.ctx.currentTime;
      const frames = Math.min(size, Math.round((time - m.lastTime) * m.ctx.sampleRate));
      if (frames <= 0) return;
      m.lastTime = time;
      const peaks = [];
      let sum = 0;
      for (let ch = 0; ch < m.channels; ch++) {
        m.raw[ch].getFloatTimeDomainData(m.buf);
        let peak = 0;
        for (let i = size - frames; i < size; i++) { const a = Math.abs(m.buf[i]); if (a > peak) peak = a; }
        peaks.push(peak);
        m.weighted[ch].getFloatTimeDomainData(m.buf);
        for (let i = size - frames; i < size; i++) sum += m.buf[i] * m.buf[i];
      }
      meterFeed(peaks, sum * WEB_K_GAIN, frames, m.ctx.sampleRate);
    }

function meterFeed(peaks, energy, frames, rate) {
      const m = meter;
      if (!m.on || frames <= 0) return;
      const now = performance.now();
      const fall = 26 * frames / rate;   // the bars fall with 26 dB per second
      for (let ch = 0; ch < m.channels; ch++) {
        const peak = Number(peaks[ch]) || 0;
        const db = toDb(peak);
        m.peakDb[ch] = Math.max(db, m.peakDb[ch] - fall);
        if (db >= m.holdDb[ch]) { m.holdDb[ch] = db; m.holdAt[ch] = now; }
        else if (now - m.holdAt[ch] > 1500) m.holdDb[ch] = Math.max(db, m.holdDb[ch] - fall);
        if (peak >= 0.999) m.clipAt = now;
        if (peak > m.blockPeak) m.blockPeak = peak;
      }
      m.energy += energy;
      m.frames += frames;
      if (m.frames >= rate / 10) {   // a block of about 100 ms: the energy of all channels together
        const block = { e: m.energy / m.frames, s: m.frames / rate, peak: m.blockPeak };
        m.energy = 0;
        m.frames = 0;
        m.blockPeak = 0;
        m.blocks.push(block);
        if (m.blocks.length > 30) m.blocks.shift();
        autoLevelBlock(block);
      }
      meterDraw();
    }

function meterDraw() {
      const m = meter;
      const loud = m.on ? lufsOf(blockEnergy(m.blocks)) : -Infinity;   // the last three seconds
      const dialog = !$('levelOverlay').hidden;
      ['L', 'R'].forEach((side, i) => {
        const ch = Math.min(i, m.channels - 1);
        const bar = $('outBar' + side);
        if (bar) bar.style.setProperty('--v', meterPos(m.peakDb[ch]));
        if (!dialog) return;
        $('lvBar' + side).style.setProperty('--v', meterPos(m.peakDb[ch]));
        $('lvHold' + side).style.setProperty('--v', meterPos(m.holdDb[ch]));
        $('lvHold' + side).classList.toggle('show', m.holdDb[ch] > METER_FLOOR_DB);
        $('lvNum' + side).textContent = m.holdDb[ch] > -90 ? dbText(m.holdDb[ch]) : '–';
      });
      const read = $('outRead');
      if (read) read.textContent = loud > -70 ? dbText(loud) : '–';
      if (!dialog) return;
      $('lvBarLoud').style.setProperty('--v', meterPos(loud));
      $('lvNumLoud').textContent = loud > -70 ? dbText(loud) : '–';
      $('lvClip').hidden = !(m.clipAt && performance.now() - m.clipAt < 2000);
    }

function renderMeterNode(node) {
      node.id = 'meterNode';
      node.classList.add('level');
      node.classList.toggle('metering', meter.on);
      node.title = meter.on ? 'Output level over USB (' + meter.label + ', channel' + (meter.channels > 1 ? 's ' : ' ') + pairText(meter.first, meter.total) +
          '): peaks left / right, below the loudness of the last three seconds – click for the meter and Auto level'
        : 'Output level: shows the level of the Nano over its USB audio and sets the capture volume from your playing';
      node.innerHTML = '<div class="sc-tile io meter"><span class="vu"><i id="outBarL"></i></span><span class="vu"><i id="outBarR"></i></span></div>' +
        (meter.on ? '<span class="sc-lbl">LUFS</span><span class="sc-sub" id="outRead">–</span>' : '<span class="sc-lbl">Meter</span>');
      node.addEventListener('click', openLevel);
    }

function renderLevel() {
      const m = meter;
      $('levelToggle').classList.toggle('on', m.on);
      $('levelToggle').setAttribute('aria-checked', String(m.on));
      const select = $('levelInput');
      select.innerHTML = '';
      if (!m.inputs.length) select.appendChild(new Option(m.starting ? 'Opening the audio input …' : 'Audio input', ''));
      m.inputs.forEach(d => select.appendChild(new Option(d.label, d.deviceId, false, m.on && d.deviceId === m.deviceId)));
      if (m.on && !m.inputs.some(d => d.deviceId === m.deviceId)) select.appendChild(new Option(m.label, m.deviceId, false, true));
      if (!m.on && m.inputs.length) select.insertBefore(new Option('Choose the audio input …', '', false, true), select.firstChild);
      select.disabled = m.starting || !m.inputs.length;
      // the channel pair, where the input delivers more than two channels
      const pair = $('levelPair');
      const nano = NANO_AUDIO.test(m.label);
      pair.innerHTML = '';
      for (let first = 1; m.on && first <= m.total; first += 2) {
        const what = !nano ? '' : first === 1 ? ' · DI' : first === 3 ? ' · sound' : '';
        pair.appendChild(new Option(pairText(first, m.total).replace('/', ' / ') + what, String(first), false, first === m.first));
      }
      pair.hidden = !(m.on && m.total > 2);
      pair.disabled = m.starting;
      const hint = $('levelHint');
      hint.classList.toggle('error', Boolean(m.error));
      hint.textContent = m.error ? m.error
        : m.starting ? ''
        : !m.on ? 'Connect the Nano to this computer with a USB-C cable and switch the meter on. The editor then reads the Nano\'s USB audio – ' +
            (nativeMeter() ? 'macOS' : 'the browser') + ' asks once for the audio input ("microphone"). Nothing is recorded.'
        : !nano ? 'This input does not look like the Nano – choose the Nano\'s USB audio above if the bars show something else.'
        : meterIsDry() && m.total < 4 ? 'The browser passes on only the first two USB channels – on the Nano that is the dry guitar signal (DI). ' +
            'Its sound with capture and effects is on channels 3/4: the Mac app reads them.'
        : meterIsDry() ? 'Channels 1/2 of the Nano carry the dry guitar signal (DI). Its sound with capture and effects is on 3/4.'
        : '';
      renderAutoLevel();
    }

function renderAutoLevel() {
      const al = autoLevel;
      $('lvTarget').style.setProperty('--v', meterPos(alTarget()));
      document.querySelectorAll('#alKinds .al-kind').forEach(el => {
        el.classList.toggle('sel', el.dataset.kind === levelStore.kind);
        const input = el.querySelector('input');
        const key = el.dataset.kind;
        if (document.activeElement !== input) input.value = key === 'clean' ? levelStore.base.toFixed(1) : (levelStore.steps[key] > 0 ? '+' : '') + levelStore.steps[key].toFixed(1);
        el.querySelector('.off').textContent = key === 'clean' ? 'the quietest sound' : 'target ' + dbText(alTarget(key)) + ' LUFS';
        input.disabled = al.running;
      });
      const kind = AL_KINDS.find(k => k.key === levelStore.kind);
      // what is remembered for the loaded preset
      const mark = state.connected ? levelMark(state.selectedPreset) : null;
      const line = $('alMark');
      line.classList.toggle('on', Boolean(mark && Math.abs(mark.lufs - alTarget(mark.kind)) <= MARK_TOLERANCE));
      const markOff = mark ? mark.lufs - alTarget(mark.kind) : 0;
      line.textContent = !state.connected ? '' : !mark ? 'Preset ' + state.selectedPreset + ' is not levelled yet.'
        : 'Preset ' + state.selectedPreset + ': ' + AL_KINDS.find(k => k.key === mark.kind).label + ', ' + dbText(mark.lufs) + ' LUFS' +
          (Math.abs(markOff) <= MARK_TOLERANCE ? ' ✓' : ' (' + dbText(markOff, true) + ' LU from its target)') + ' · ' + new Date(mark.at).toLocaleDateString() +
          (mark.saved ? '' : ' · press Save to keep it');
      if (mark && !al.running && !al.preparing) {
        const forget = document.createElement('button');
        forget.type = 'button';
        forget.className = 'al-link';
        forget.textContent = 'Forget';
        forget.title = 'Remove this note (the preset itself stays as it is)';
        forget.addEventListener('click', () => { levelMarkDrop(state.selectedPreset); renderPresetSelect(); });
        line.appendChild(forget);
      }
      $('alStatus').classList.toggle('error', al.error);
      $('alStatus').textContent = al.text || 'Play the way you would in the song – chords for a rhythm sound, a lead line for a solo sound.';
      if (al.last && !al.running && !al.error && al.last.offerTarget) {
        const use = document.createElement('button');
        use.type = 'button';
        use.className = 'al-link';
        use.textContent = 'Take ' + dbText(al.last.loud) + ' LUFS as the ' + AL_KINDS.find(k => k.key === al.last.kind).label + ' target (the others move along)';
        use.addEventListener('click', () => autoLevelTakeTarget());
        $('alStatus').appendChild(use);
      }
      $('alBar').style.setProperty('--v', (al.running ? clamp(al.played / AL_SECONDS, 0, 1) * 100 : 0) + '%');
      const asked = !al.running && al.levelAsk === state.selectedPreset;   // Level is not at 10: the next press sets it
      $('alStart').textContent = al.running ? 'Stop' : asked ? 'Set Level to 10 and start' : 'Start';
      $('alStart').title = al.running ? '' : 'Listens for ' + AL_SECONDS + ' seconds of playing and sets the capture volume for a ' + kind.label + ' sound';
      $('alStart').disabled = al.preparing;
      $('alOnly').hidden = al.running;
      $('alOnly').disabled = al.preparing;
      $('alUndo').hidden = al.running || al.preparing || !al.undo;
      $('alUndo').title = al.undo && al.undo.level < LEVEL_FULL ? 'Back to the capture volume and the Level from before' : 'Back to the capture volume from before';
      $('alReset').hidden = levelStore.base === AL_BASE && Object.keys(AL_STEPS).every(key => levelStore.steps[key] === AL_STEPS[key]);
      document.querySelectorAll('#alProfileBox .seg').forEach(b => {
        b.classList.toggle('on', b.dataset.profile === levelStore.profile);
        b.disabled = al.running;
      });
      $('alProfileText').textContent = AL_PROFILES[levelStore.profile].text;
    }

async function openLevel() {
      const levelled = state.connected ? levelMark(state.selectedPreset) : null;
      if (levelled && !autoLevel.running) levelStore.kind = levelled.kind;   // the kind this preset was levelled as
      $('levelOverlay').hidden = false;
      renderLevel();
      meterDraw();
      $('levelClose').focus();
      if (!meter.on && !meter.userOff) { await meterStart(''); return; }
      if (!nativeMeter()) return;
      const listed = await nativeMeter().list();   // the inputs as they are now
      if (!listed.devices) return;
      meter.inputs = listed.devices.map(d => ({ deviceId: d.uid, label: d.name, channels: d.channels, standard: d.default }));
      renderLevel();
    }

const LEVEL_FULL = 255;

const MARK_TOLERANCE = 0.5;

const captureRawNow = () => captureDbToRaw(Number(state.captureVolumeDb) || 0);

function levelMark(preset) {
      const mark = levelStore.marks[preset];
      if (!mark || !AL_KINDS.some(k => k.key === mark.kind) || mark.name !== (state.presetNames.get(preset) || '')) return null;
      if (preset === state.selectedPreset) return mark.raw === captureRawNow() && state.amp.level === LEVEL_FULL ? mark : null;
      return mark.saved ? mark : null;
    }

function levelMarkSet(preset, kind, lufs, saved) {
      levelStore.marks[preset] = { kind, lufs: Math.round(lufs * 10) / 10, raw: captureRawNow(), name: state.presetNames.get(preset) || '', saved, at: Date.now() };
      saveLevelStore();
    }

function levelMarkDrop(preset) {
      if (!levelStore.marks[preset]) return;
      delete levelStore.marks[preset];
      saveLevelStore();
    }

function levelMarkCheck() {
      const preset = state.selectedPreset;
      const mark = levelStore.marks[preset];
      if (!mark || presetUnsaved()) return;
      if (mark.raw !== captureRawNow() || state.amp.level !== LEVEL_FULL || mark.name !== (state.presetNames.get(preset) || '')) levelMarkDrop(preset);
      else if (!mark.saved) { mark.saved = true; saveLevelStore(); }
    }

function autoLevelCancel(text, error = false) {
      const al = autoLevel;
      if (!al.running && !text) return;
      al.running = false;
      al.text = text;
      al.error = error;
      if (!$('levelOverlay').hidden) renderAutoLevel();
    }

function autoLevelBlock(block) {
      const al = autoLevel;
      if (!al.running) return;
      const waited = (performance.now() - al.startedAt) / 1000;
      if (state.selectedPreset !== al.preset || (al.apply && !state.connected)) { autoLevelCancel('Stopped: the preset changed.', true); return; }
      if (lufsOf(block.e) > AL_PLAY_LUFS) {
        al.blocks.push(block);
        al.played += block.s;
        if (block.peak > al.peak) al.peak = block.peak;
        al.text = 'Measuring – keep playing … ' + Math.min(AL_SECONDS, al.played).toFixed(1) + ' of ' + AL_SECONDS + ' s';
      }
      if (al.played >= AL_SECONDS || (waited > 30 && al.played >= 1.5)) { autoLevelFinish(); return; }
      if (waited > 12 && al.played === 0) {
        autoLevelCancel('No signal came. Is the Nano connected over USB and chosen as the audio input above, and is the guitar up?', true);
        return;
      }
      if (waited > 30) { autoLevelCancel('That was too little playing to measure.', true); return; }
      renderAutoLevel();
    }

async function autoLevelFinish() {
      const al = autoLevel;
      al.running = false;
      const kind = AL_KINDS.find(k => k.key === al.kind);
      const target = alTarget(al.kind);
      const loud = gatedLoudness(al.blocks);
      const peakDb = toDb(al.peak);
      const levelRaised = Boolean(al.before && al.before.level < LEVEL_FULL);
      const measured = 'Measured ' + dbText(loud) + ' LUFS, peaks up to ' + dbText(peakDb) + ' dBFS' + (al.before ? ', with Level at 10' : '') + '.';
      const levelNote = levelRaised ? ' Level was at ' + ampText(al.before.level) + ' and stays at 10 now.' : '';
      al.last = { loud, peakDb, kind: al.kind, offerTarget: !al.apply };
      if (levelRaised) al.undo = al.before;
      // the mark of this preset: what it measures now (nothing unsaved and nothing changed: it is the stored preset)
      const mark = lufsNow => { if (al.before && Number.isFinite(lufsNow)) levelMarkSet(al.preset, al.kind, lufsNow, !levelRaised && !presetUnsaved()); };
      if (!al.apply) {
        al.text = measured + ' The ' + kind.label + ' target is ' + dbText(target) + ' LUFS (' + dbText(target - loud, true) + ' dB from here).' + levelNote;
        mark(loud);
        renderLevel();
        renderPresetSelect();
        return;
      }
      let change = target - loud;
      let limit = '';
      if (peakDb + change > AL_CEILING_DB) {
        change = AL_CEILING_DB - peakDb;
        limit = ' The target would clip: the level stops where the peaks reach ' + dbText(AL_CEILING_DB) + ' dBFS.';
      }
      const before = al.before ? al.before.db : Number(state.captureVolumeDb) || 0;
      const after = Math.round(clamp(before + change, -24, 12) * 10) / 10;
      if (after !== Math.round((before + change) * 10) / 10) limit = ' The capture volume is at its ' + (after >= 12 ? 'upper' : 'lower') + ' end: ' +
        dbText(Math.abs(before + change - after)) + ' dB ' + (after >= 12 ? 'more' : 'less') + ' would be needed. An effect level or the gain can do the rest.';
      if (Math.abs(after - before) < 0.05) {
        al.text = measured + NL + (limit ? 'Capture volume unchanged at ' + dbText(before, true) + ' dB.' + limit
          : 'That is the ' + kind.label + ' target (' + dbText(target) + ' LUFS) – nothing to change.') + levelNote;
        mark(loud);
        renderLevel();
        renderPresetSelect();
        return;
      }
      al.undo = al.before || { preset: state.selectedPreset, db: before, level: LEVEL_FULL };
      setCaptureVolumeUI(after);
      await setCaptureVolumeDb(after);
      if (al.before) levelMarkSet(al.preset, al.kind, loud + after - before, false);   // counts once the preset is saved
      al.text = measured + NL + 'Capture volume ' + dbText(before, true) + ' → ' + dbText(after, true) + ' dB (' + dbText(after - before, true) + ' dB) for the ' +
        kind.label + ' target of ' + dbText(target) + ' LUFS.' + limit + levelNote + (state.capture.on ? '' : ' The capture is off in this preset – its volume may do nothing.') +
        NL + 'Press Start again to check it, and Save to keep it.';
      log('Auto level (' + kind.label + '): ' + al.text.split(NL).join(' '));
      renderLevel();
      renderPresetSelect();
    }

function autoLevelTakeTarget() {
      const al = autoLevel;
      if (!al.last || !Number.isFinite(al.last.loud)) return;
      levelStore.base = Math.round(clamp(levelStore.base + al.last.loud - alTarget(al.last.kind), -40, -8) * 10) / 10;
      saveLevelStore();
      al.text = AL_PROFILES[levelStore.profile].label + ' targets: ' + AL_KINDS.map(k => k.label + ' ' + dbText(alTarget(k.key))).join(', ') + ' LUFS.';
      al.last = null;
      renderLevel();
    }

function renderSignalChain() {
      const box = $('signalChain');
      if (!box) return;
      const slotLabel = slot => (slot ? Math.floor((slot - 1) / 5) + 1 + '-' + ((slot - 1) % 5 + 1) : '');
      const fx = key => {
        const block = state.blocks[key];
        const model = block.models.find(m => m.name === block.model);
        const style = fxStyle(model);
        return { key, label: block.title, sub: block.model === 'None' ? 'empty' : block.model, icon: style.icon, color: style.color,
          state: block.model === 'None' ? 'empty' : block.on ? 'on' : 'off', target: 'block-' + key,
          toggle: () => { const t = document.querySelector('#block-' + key + ' > .block-head .toggle-switch'); if (t) t.click(); } };
      };
      const captureType = state.capture.on ? currentCaptureType() : null;
      const nodes = [
        { io: 'IN' },
        { key: 'gate', label: 'Gate', sub: state.gate.params[0] ? Math.round(state.gate.params[0].value) + ' %' : '', icon: 'gate', color: '#F2F2F2',
          state: state.gate.on ? 'on' : 'off', target: 'gateCard', toggle: () => $('gateToggle').click() },
        fx('pre1'), fx('pre2'),
        { key: 'capture', wide: true, label: (captureType && captureType.key !== 'default' ? captureType.label : 'Capture') +
            (state.capture.on && state.capture.activeSlot ? ' · ' + slotLabel(state.capture.activeSlot) : ''),
          name: state.capture.on ? state.currentCapture.name || 'Capture' : 'Bypassed', icon: captureType ? captureType.icon : 'capture', color: '#F2F2F2',
          state: state.capture.on ? 'on' : 'off', target: 'captureCard', toggle: () => $('captureToggle').click() },
        { key: 'cab', wide: true, label: 'Cab' + (state.cabIR.on && state.cabIR.stateSlot ? ' · ' + state.cabIR.stateSlot : ''),
          name: state.cabIR.on ? state.currentIR.shortName || 'Cab / IR' : 'Bypassed', icon: 'cab', color: '#F2F2F2',
          state: state.cabIR.on ? 'on' : 'off', target: 'cabCard', toggle: () => $('cabIRToggle').click() },
        fx('post1'), fx('post2'), fx('post3'),
        { meter: true },
        { io: 'OUT' }
      ];
      box.innerHTML = '';
      nodes.forEach(n => {
        const node = document.createElement('div');
        if (n.io || n.meter) {
          node.className = 'sc-node io';
          if (n.meter) renderMeterNode(node);
          else {
            node.innerHTML = '<div class="sc-tile io">' + n.io + '</div>';
            if (state.connected) renderMuteNode(node, n.io === 'IN' ? 'in' : 'out');
          }
          box.appendChild(node);
          return;
        }
        node.className = 'sc-node' + (n.wide ? ' wide' : '');
        const icon = n.icon ? '<span class="ico" style="--icon: var(--ico-' + n.icon + ')"></span>' : '';
        node.innerHTML = '<div class="sc-tile ' + n.state + '" style="--c:' + n.color + ';--ink:' + iconInk(n.color) + '">' + icon +
          (n.wide ? '<span class="nm">' + escapeHTML(n.name) + '</span>' : '') + '</div>' +
          '<span class="sc-lbl">' + escapeHTML(n.label) + '</span>' + (n.wide ? '' : '<span class="sc-sub">' + escapeHTML(n.sub || '') + '</span>');
        node.title = n.label + (n.wide ? ': ' + n.name : n.sub ? ': ' + n.sub : '') + ' - double-click: on / off';
        node.addEventListener('click', () => {
          const target = $(n.target);
          if (!target) return;
          target.style.setProperty('--flash', n.color);
          target.classList.remove('flash');
          void target.offsetWidth;
          target.classList.add('flash');
        });
        node.addEventListener('dblclick', e => {
          e.preventDefault();
          if (n.state === 'empty') return;
          n.toggle();
        });
        box.appendChild(node);
      });
    }

    function render() { /* replaced by pro/ui.js */ }

function disconnect() {
      if (state.device && state.device.gatt.connected) {
        state.device.gatt.disconnect();
      } else {
        onDisconnected();
      }
    }

state.mc6 = { selected: [1, 2, 3, 4, 5], channel: 1, bankName: 'Nano Cortex', mixSlot: -1, records: {}, busy: false };

function waitForPresetState(preset, timeoutMs) {
      return new Promise(resolve => {
        const done = ok => { clearTimeout(timer); presetStateWaiters.splice(presetStateWaiters.indexOf(waiter), 1); resolve(ok); };
        const waiter = () => { if (state.selectedPreset === preset) done(true); };
        const timer = setTimeout(() => done(false), timeoutMs);
        presetStateWaiters.push(waiter);
      });
    }

function renderMc6Panel() {
      const ch = $('mc6Channel');
      if (!ch.options.length) ch.innerHTML = Array.from({ length: 16 }, (_, i) => '<option value="' + (i + 1) + '">' + (i + 1) + '</option>').join('');
      ch.value = String(state.mc6.channel);
      $('mc6BankName').value = state.mc6.bankName;
      $('mc6MixSlot').value = String(state.mc6.mixSlot);
      const sel = state.mc6.selected.slice().sort((a, b) => a - b);
      $('mc6Count').textContent = sel.length + ' of 5 presets selected (A–E in preset order)';
      const list = $('mc6Presets');
      list.innerHTML = '';
      for (let i = 1; i <= 64; i++) {
        const idx = sel.indexOf(i);
        const row = document.createElement('label');
        row.className = 'mc6-preset' + (idx >= 0 ? ' on' : '') + (idx < 0 && sel.length >= 5 ? ' disabled' : '');
        row.innerHTML = '<input type="checkbox"' + (idx >= 0 ? ' checked' : '') + (idx < 0 && sel.length >= 5 ? ' disabled' : '') + '>' +
          '<span class="n">' + i + '</span><span class="name">' + escapeHTML(state.presetNames.get(i) || 'Preset ' + i) + '</span>' +
          (idx >= 0 ? '<span class="mc6-letter">' + 'ABCDE'[idx] + '</span>' : '');
        row.querySelector('input').addEventListener('change', e => {
          if (e.target.checked) { if (state.mc6.selected.length < 5) state.mc6.selected.push(i); }
          else state.mc6.selected = state.mc6.selected.filter(x => x !== i);
          renderMc6Panel();
        });
        list.appendChild(row);
      }
    }

const MIDI_STORE = 'nanoCortexMidi';

state.midi = { access: null, learn: false, learnTarget: null, map: {}, pickup: false, pcToPreset: false, input: 'all', picked: {}, last: {}, renderTimer: null, decorateQueued: false };

function midiTargetId(t) {
      return t.kind + ':' + (t.block || '') + ':' + (t.param || t.key || t.target || '');
    }

function midiEl(target) {
      return document.querySelector('[data-midi-id="' + CSS.escape(midiTargetId(target)) + '"]');
    }

const isMidiButton = t => t.kind === 'toggle' || t.kind === 'tuner' || t.kind === 'preset' || t.kind === 'jam';

function midiKeyLabel(key) {
      const [type, ch, num] = key.split(':');
      return (type === 'cc' ? 'CC ' : 'Note ') + num + (ch !== '1' ? ' · Ch ' + ch : '');
    }

function midiTargetLabel(t) {
      const blockTitle = key => key === 'gate' ? 'Gate' : (state.blocks[key] ? state.blocks[key].title : key);
      switch (t.kind) {
        case 'param': return blockTitle(t.block) + ' · ' + t.param;
        case 'amp': return 'Amp · ' + ((AMP_KNOBS.find(k => k.key === t.key) || {}).label || t.key);
        case 'captureVolume': return 'Capture Volume';
        case 'cab': return 'Cab · ' + { level: 'Level', highPass: 'High Pass', lowPass: 'Low Pass' }[t.key];
        case 'toggle': return ({ capture: 'Capture', cab: 'Cab / IR', gate: 'Gate' }[t.target] || blockTitle(t.target)) + ' on/off';
        case 'tuner': return 'Tuner on/off';
        case 'preset': return t.key === 'prev' ? 'Previous preset' : 'Next preset';
        case 'jam': return 'Jam tracks · ' + { prev: 'previous track', play: 'play / pause', next: 'next track' }[t.key];
      }
      return midiTargetId(t);
    }

function saveMidiSettings() {
      try {
        localStorage.setItem(MIDI_STORE, JSON.stringify({ map: state.midi.map, pickup: state.midi.pickup, pcToPreset: state.midi.pcToPreset, input: state.midi.input }));
      } catch (err) { log('Could not save MIDI settings: ' + err.message); }
    }

function controllerSwitch(data) {
      const fields = framePayloadFields(data);
      const number = fields[1] && fields[1][0] ? fields[1][0].value : 0;
      if (number < 1 || number > 8) return;
      log('Controller footswitch ' + number);
      handleMidiData([0xBF, 100 + number, 127]);
      handleMidiData([0xBF, 100 + number, 0]);
    }

function handleMidiData(data) {
      const status = data[0] & 0xF0;
      const channel = (data[0] & 0x0F) + 1;

      if (status === 0xC0) {
        if (state.midi.pcToPreset && !state.midi.learn) selectPreset(Math.min(64, data[1] + 1));
        return;
      }

      let key, value;
      if (status === 0xB0) { key = 'cc:' + channel + ':' + data[1]; value = data[2]; }
      else if (status === 0x90 || status === 0x80) { key = 'note:' + channel + ':' + data[1]; value = status === 0x90 && data[2] > 0 ? 127 : 0; }
      else return;

      if (state.midi.learn) {
        if (state.midi.learnTarget && (status === 0xB0 || value > 0)) assignMidi(key);
        return;
      }
      const mapping = state.midi.map[key];
      if (mapping) applyMidi(key, mapping, value);
    }

function assignMidi(key) {
      const target = state.midi.learnTarget;
      const id = midiTargetId(target);
      Object.keys(state.midi.map).forEach(k => { if (midiTargetId(state.midi.map[k].target) === id) delete state.midi.map[k]; });
      state.midi.map[key] = { target, mode: 'toggle' };
      delete state.midi.picked[key];
      saveMidiSettings();
      log('MIDI assigned: ' + midiKeyLabel(key) + ' -> ' + midiTargetLabel(target));
      $('midiBannerText').innerHTML = '<b>' + escapeHTML(midiKeyLabel(key)) + '</b> → ' + escapeHTML(midiTargetLabel(target)) + '. Click the next control, or press Done.';
      state.midi.learnTarget = null;
      document.querySelectorAll('.midi-selected').forEach(el => el.classList.remove('midi-selected'));
      decorateMidi();
      renderMidiPanel();
    }

function removeMidi(key) {
      delete state.midi.map[key];
      saveMidiSettings();
      decorateMidi();
      renderMidiPanel();
    }

function midiCurrentValue(t) {
      switch (t.kind) {
        case 'amp': return state.amp[t.key] / 255;
        case 'param': {
          const block = t.block === 'gate' ? state.gate : state.blocks[t.block];
          const param = block && block.params.find(p => p.name === t.param);
          return param ? paramValueToNormalized(param) : null;
        }
        case 'captureVolume': return (Number($('captureVolumeSlider').value) + 24) / 36;
        case 'cab': {
          return cabIRValueToNormalized(t.key, ({ level: state.cabIR.levelDb, highPass: state.cabIR.highPassHz, lowPass: state.cabIR.lowPassHz })[t.key]);
        }
      }
      return null;
    }

function resetMidiPickup() {
      state.midi.picked = {};
    }

function applyMidi(key, mapping, value) {
      const t = mapping.target;
      const previous = state.midi.last[key];
      state.midi.last[key] = value;

      if (isMidiButton(t)) {
        const pressed = value >= 64;
        if (mapping.mode === 'latch') { if (t.kind !== 'preset' && t.kind !== 'jam') setMidiButton(t, pressed); else if (pressed && !(previous >= 64)) triggerMidiButton(t); return; }
        if (pressed && !(previous >= 64)) triggerMidiButton(t); // every press toggles
        return;
      }

      const v = value / 127;
      if (state.midi.pickup && !state.midi.picked[key]) {
        const current = midiCurrentValue(t);
        if (current === null) return;
        const crossed = previous !== undefined && (previous / 127 - current) * (v - current) <= 0;
        if (Math.abs(v - current) > 2 / 127 && !crossed) return; // knob has not reached the current value yet
        state.midi.picked[key] = true;
      }
      setMidiValue(t, v);
    }

function midiButtonIsOn(t) {
      if (t.kind === 'tuner') return state.tuner.open;
      if (t.target === 'gate') return state.gate.on;
      if (t.target === 'capture') return state.capture.on;
      if (t.target === 'cab') return state.cabIR.on;
      return Boolean(state.blocks[t.target] && state.blocks[t.target].on);
    }

function triggerMidiButton(t) {
      if (t.kind === 'tuner') { if (state.tuner.open) closeTuner(); else openTuner(false); return; }
      const el = midiEl(t);
      if (el) el.click();
    }

function setMidiButton(t, on) {
      if (midiButtonIsOn(t) !== on) triggerMidiButton(t);
    }

function setMidiValue(t, v) {
      const el = midiEl(t);
      const valueEl = el && el.parentElement ? el.parentElement.querySelector('.value-text') : null;

      if (t.kind === 'amp') {
        const raw = Math.round(v * 255);
        if (raw === state.amp[t.key]) return;
        state.amp[t.key] = raw;
        if (el && valueEl) updateKnobVisual(el, valueEl, raw / 255, ampText(raw));
        setAmpKnob(t.key, raw);
        return;
      }

      if (t.kind === 'param') {
        const block = t.block === 'gate' ? state.gate : state.blocks[t.block];
        const param = block && block.params.find(p => p.name === t.param);
        if (!param) return; // the model in this slot has no parameter with this name
        const meta = param.meta || rangeMeta(0, 10, 0.1, '', 1);
        const raw = normalizedToParamValue(param, v);
        const next = coerceParamValue(param, raw);
        if (next === null || next === param.value) return;
        param.value = next;
        if (meta.kind === 'enum') scheduleMidiRender();
        else if (el && valueEl) updateKnobVisual(el, valueEl, paramValueToNormalized(param), paramDisplayValue(param));
        sendParamValue(t.block, param);
        return;
      }

      if (t.kind === 'captureVolume') {
        const db = Math.round((-24 + v * 36) * 10) / 10;
        setCaptureVolumeUI(db);
        setCaptureVolumeDb(db);
        return;
      }

      if (t.kind === 'cab') {
        const [min, max, step] = CAB_RANGES[t.key];
        const value = roundToStep(cabIRNormalizedToValue(t.key, v), step);
        const text = el && el.parentElement.querySelector('.value-text');
        if (el && text) updateKnobVisual(el, text, cabIRValueToNormalized(t.key, value), formatCabValue(t.key, value));
        ({ level: setCabIRLevelDb, highPass: setCabIRHighPassHz, lowPass: setCabIRLowPassHz })[t.key](value);
      }
    }

function scheduleMidiRender() {
      if (state.midi.renderTimer) return;
      state.midi.renderTimer = setTimeout(() => { state.midi.renderTimer = null; render(); }, 100);
    }

function decorateMidi() {
      state.midi.decorateQueued = false;
      const byId = {};
      Object.entries(state.midi.map).forEach(([key, m]) => { byId[midiTargetId(m.target)] = key; });
      document.querySelectorAll('[data-midi-id]').forEach(el => {
        const key = byId[el.dataset.midiId];
        const container = el.closest('.knob-param, .switch-param, .stepped-param, .placeholder-param');
        let badge = container ? container.querySelector(':scope > .midi-badge') : null;
        if (key) {
          el.dataset.midiMapped = midiKeyLabel(key);
          el.title = (el.dataset.tip ? el.dataset.tip + ' · ' : '') + 'MIDI: ' + midiKeyLabel(key) + ' (right-click to remove)';
          if (container) {
            if (!badge) { badge = document.createElement('span'); badge.className = 'midi-badge'; container.appendChild(badge); }
            badge.textContent = midiKeyLabel(key);
          }
        } else {
          if (el.dataset.midiMapped) {
            delete el.dataset.midiMapped;
            if (el.dataset.tip) el.title = el.dataset.tip; else el.removeAttribute('title');
          }
          if (badge) badge.remove();
        }
      });
    }

function renderMidiPanel() {
      if ($('midiOverlay').hidden) return;
      const inputs = state.midi.access ? Array.from(state.midi.access.inputs.values()) : [];
      $('midiStatus').textContent = state.midi.access
        ? (inputs.length ? 'Connected MIDI inputs: ' + inputs.map(i => i.name).join(', ') : 'No MIDI controller found. Connect one via USB or Bluetooth MIDI.')
        : 'MIDI access has not been granted yet.';

      const select = $('midiInput');
      select.innerHTML = '<option value="all">All inputs</option>' + inputs.map(i => '<option value="' + escapeHTML(i.id) + '">' + escapeHTML(i.name) + '</option>').join('');
      select.value = inputs.some(i => i.id === state.midi.input) ? state.midi.input : 'all';
      $('midiPickup').checked = state.midi.pickup;
      $('midiPc').checked = state.midi.pcToPreset;

      const list = $('midiList');
      const entries = Object.entries(state.midi.map).sort((a, b) => midiTargetLabel(a[1].target).localeCompare(midiTargetLabel(b[1].target)));
      list.innerHTML = entries.length ? '' : '<div class="lib-empty">No assignments yet. Press "Start MIDI Learn".</div>';
      entries.forEach(([key, m]) => {
        const row = document.createElement('div');
        row.className = 'midi-map-row';
        const modeSelect = isMidiButton(m.target) && m.target.kind !== 'preset'
          ? '<select><option value="toggle"' + (m.mode !== 'latch' ? ' selected' : '') + '>Each press toggles</option><option value="latch"' + (m.mode === 'latch' ? ' selected' : '') + '>Button value = on/off</option></select>'
          : '<span></span>';
        row.innerHTML = '<span class="src">' + escapeHTML(midiKeyLabel(key)) + '</span><span>' + escapeHTML(midiTargetLabel(m.target)) + '</span>' + modeSelect + '<button class="btn-small">Remove</button>';
        const sel = row.querySelector('select');
        if (sel) sel.addEventListener('change', () => { m.mode = sel.value; saveMidiSettings(); });
        row.querySelector('button').addEventListener('click', () => removeMidi(key));
        list.appendChild(row);
      });
    }

const JAM_STORE = 'nanoCortexJam';

const jamConverter = () => window.nanoJam || null;

const JAM_CEILING_DB = -1;

const JAM_BASS_HZ = 200;

const JAM_BASS_USUAL_DB = 1.4;

const JAM_BASS_MOST_DB = 3;

const JAM_BASS_NOTE_DB = 0.5;

const jamStore = { open: false, offset: -2, repeat: false, output: '', cache: {}, trim: {} };

function saveJamStore() {
      const keys = Object.keys(jamStore.cache);
      keys.slice(0, Math.max(0, keys.length - 600)).forEach(key => delete jamStore.cache[key]);   // the oldest go
      const trims = Object.keys(jamStore.trim);
      trims.slice(0, Math.max(0, trims.length - 2000)).forEach(path => delete jamStore.trim[path]);
      try { localStorage.setItem(JAM_STORE, JSON.stringify(jamStore)); } catch (e) { /* storage unavailable */ }
    }

const jam = { tracks: [], folder: '', index: -1, audio: null, ctx: null, gain: null, url: '', decoder: null, measuring: 0, run: 0, load: 0,
      converted: null, outputs: [], list: false };

state.usbReturnDb = null;

const jamTarget = () => alTarget('drive') + jamStore.offset;

const jamUsbDb = () => (state.connected && Number.isFinite(state.usbReturnDb) ? state.usbReturnDb : 0);

const jamTrack = () => jam.tracks[jam.index] || null;

const jamTrim = track => (track && jamStore.trim[track.path]) || 0;

const jamBass = track => (track && Number.isFinite(track.lufs) && Number.isFinite(track.play) ? track.lufs - track.play : 0);

function jamGain(track) {
      if (!track || !Number.isFinite(track.lufs)) return { db: 0, limited: false };
      const wanted = jamTarget() + jamTrim(track) - track.play - jamUsbDb();
      const most = JAM_CEILING_DB - toDb(track.peak || 1);
      return { db: Math.min(wanted, most), limited: wanted > most + 0.05 };
    }

function jamApplyGain() {
      if (jam.gain) jam.gain.gain.value = Math.pow(10, jamGain(jamTrack()).db / 20);
    }

function kWeighting(rate) {
      let k = Math.tan(Math.PI * 1681.974450955533 / rate);
      let q = 0.7071752369554196;
      const vh = Math.pow(10, 3.999843853973347 / 20), vb = Math.pow(vh, 0.4996667741545416);
      let a0 = 1 + k / q + k * k;
      const shelf = [(vh + vb * k / q + k * k) / a0, 2 * (k * k - vh) / a0, (vh - vb * k / q + k * k) / a0, 2 * (k * k - 1) / a0, (1 - k / q + k * k) / a0];
      k = Math.tan(Math.PI * 38.13547087602444 / rate);
      q = 0.5003270373238773;
      a0 = 1 + k / q + k * k;
      return [shelf, [1, -2, 1, 2 * (k * k - 1) / a0, (1 - k / q + k * k) / a0]];
    }

function highPass(rate, hz) {
      const w = 2 * Math.PI * hz / rate, cos = Math.cos(w), alpha = Math.sin(w) / Math.SQRT2;
      const a0 = 1 + alpha;
      return [(1 + cos) / 2 / a0, -(1 + cos) / a0, (1 + cos) / 2 / a0, -2 * cos / a0, (1 - alpha) / a0];
    }

function bufferLoudness(buffer) {
      const hop = Math.round(buffer.sampleRate / 10);
      const count = Math.floor(buffer.length / hop);
      const energy = new Float64Array(count), noBass = new Float64Array(count);
      const [s, h] = kWeighting(buffer.sampleRate);
      const c = highPass(buffer.sampleRate, JAM_BASS_HZ);
      let peak = 0;
      for (let ch = 0; ch < buffer.numberOfChannels; ch++) {
        const data = buffer.getChannelData(ch);
        let s1 = 0, s2 = 0, h1 = 0, h2 = 0, c1 = 0, c2 = 0;   // filter states (transposed direct form II)
        for (let block = 0, i = 0; block < count; block++) {
          let sum = 0, cut = 0;
          for (const end = i + hop; i < end; i++) {
            const x = data[i];
            const a = x < 0 ? -x : x;
            if (a > peak) peak = a;
            const y = s[0] * x + s1;
            s1 = s[1] * x - s[3] * y + s2;
            s2 = s[2] * x - s[4] * y;
            const z = h[0] * y + h1;
            h1 = h[1] * y - h[3] * z + h2;
            h2 = h[2] * y - h[4] * z;
            sum += z * z;
            const w = c[0] * z + c1;
            c1 = c[1] * z - c[3] * w + c2;
            c2 = c[2] * z - c[4] * w;
            cut += w * w;
          }
          energy[block] += sum / hop;
          noBass[block] += cut / hop;
        }
      }
      const both = buffer.numberOfChannels === 1 ? 2 : 1;
      const gated = list => gatedLoudness(Array.from(list, e => ({ e: e * both, s: 0.1 })));
      const lufs = gated(energy);
      return { lufs, play: Math.max(gated(noBass) + JAM_BASS_USUAL_DB, lufs - JAM_BASS_MOST_DB), peak };
    }

async function jamConverted(track) {
      if (jam.converted && jam.converted.key === track.key) return jam.converted.blob;
      if (!jamConverter()) return null;
      const reply = await jamConverter().convert(track.file);
      if (!reply || !reply.data) {
        log('Jam tracks: "' + track.name + '" not converted' + (reply && reply.error ? ': ' + reply.error : ''));
        return null;
      }
      const blob = new Blob([reply.data], { type: 'audio/wav' });
      jam.converted = { key: track.key, blob };
      return blob;
    }

function jamMeasure(track) {
      if (Number.isFinite(track.lufs) || track.error) return Promise.resolve();
      if (!track.pending) track.pending = jamMeasureNow(track).finally(() => { track.pending = null; });
      return track.pending;
    }

async function jamMeasureNow(track) {
      if (!jam.decoder) jam.decoder = new OfflineAudioContext(2, 1, 48000);
      let buffer = null, why = '';
      if (!track.convert) {
        try { buffer = await jam.decoder.decodeAudioData(await track.file.arrayBuffer()); } catch (err) { why = (err && err.message) || 'not decoded'; }
      }
      if (!buffer && jamConverter()) {   // not the browser's: macOS reads it
        const blob = await jamConverted(track);
        try { if (blob) buffer = await jam.decoder.decodeAudioData(await blob.arrayBuffer()); } catch (err) { why = (err && err.message) || 'not decoded'; }
        track.convert = Boolean(buffer);
      }
      const result = buffer ? bufferLoudness(buffer) : null;
      if (result && Number.isFinite(result.lufs) && Number.isFinite(result.play)) {
        track.lufs = Math.round(result.lufs * 100) / 100;
        track.play = Math.round(result.play * 100) / 100;
        track.peak = Math.round(result.peak * 1000) / 1000;
        jamStore.cache[track.key] = [track.lufs, track.peak, track.convert ? 1 : 0, track.play];
        saveJamStore();
        return;
      }
      track.error = buffer ? 'silent' : /\.(m4a|m4b|aif|aiff|aifc|caf)$/i.test(track.file.name) && !jamConverter() ? 'only the Mac app reads this (Apple Lossless, AIFF)' : 'not readable';
      log('Jam tracks: "' + track.name + '" ' + track.error + (why ? ' (' + why + ')' : ''));
    }

async function jamMeasureAll() {
      const run = ++jam.run;
      for (;;) {
        const current = jamTrack();
        const next = current && !Number.isFinite(current.lufs) && !current.error ? current
          : jam.tracks.find(track => !Number.isFinite(track.lufs) && !track.error);
        if (!next || run !== jam.run) break;
        jam.measuring = jam.tracks.filter(track => !Number.isFinite(track.lufs) && !track.error).length;
        renderJam();
        await jamMeasure(next);
        if (run !== jam.run) return;
        if (next === jamTrack()) jamApplyGain();
        await wait(10);   // the window stays usable between two tracks
      }
      if (run === jam.run) { jam.measuring = 0; renderJam(); }
    }

function jamPlayer() {
      if (jam.audio) return jam.audio;
      const audio = new Audio();
      audio.preload = 'auto';
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const gain = ctx.createGain();
      ctx.createMediaElementSource(audio).connect(gain);
      gain.connect(ctx.destination);
      Object.assign(jam, { audio, ctx, gain });
      audio.addEventListener('ended', () => { if (jamStore.repeat) { audio.currentTime = 0; audio.play().catch(() => {}); } else jamStep(1, true); });
      ['play', 'pause', 'loadedmetadata', 'emptied'].forEach(type => audio.addEventListener(type, renderJam));
      audio.addEventListener('timeupdate', renderJamTime);
      audio.addEventListener('error', () => {
        const track = jamTrack();
        if (!track || !audio.src) return;
        track.error = 'not playable';
        renderJam();
      });
      jamOutputs();
      return audio;
    }

async function jamOutputs() {
      if (!jam.ctx || !jam.ctx.setSinkId || !navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return;
      try {
        const all = (await navigator.mediaDevices.enumerateDevices()).filter(d => d.kind === 'audiooutput' && d.label && d.deviceId !== 'communications');
        jam.outputs = all.filter(d => d.deviceId !== 'default');
        const wanted = jam.outputs.find(d => d.label === jamStore.output) || (jamStore.output ? null : jam.outputs.find(d => NANO_AUDIO.test(d.label)));
        await jam.ctx.setSinkId(wanted ? wanted.deviceId : '');
        jam.sink = wanted ? wanted.deviceId : '';
      } catch (err) {
        log('Jam tracks: output not set (' + err.message + ')');
      }
      renderJam();
    }

function jamStop() {
      if (!jam.audio) return;
      jam.audio.pause();
      jam.audio.removeAttribute('src');
      jam.audio.load();
      if (jam.url) URL.revokeObjectURL(jam.url);
      jam.url = '';
    }

async function jamLoad(index, play) {
      const track = jam.tracks[index];
      if (!track) return;
      const audio = jamPlayer();
      jamStop();
      jam.index = index;
      const load = ++jam.load;
      if (state.connected && state.stateMode === 'idle') writeC304('Retrieve settings', buildFrame([0x08, 0x03], MSG.RetrieveSettingsRequest));   // the USB playback volume as it is now
      renderJam();
      if (!Number.isFinite(track.lufs) && !track.error) {
        jamMeasureAll();   // this one first
        await waitUntil(() => Number.isFinite(track.lufs) || track.error || load !== jam.load, 120000);
      }
      if (load !== jam.load) return;   // another track was chosen meanwhile
      const sound = track.error ? null : track.convert ? await jamConverted(track) : track.file;
      if (load !== jam.load) return;
      if (!sound) {
        if (!track.error) track.error = 'not readable';
        renderJam();
        return;
      }
      jam.url = URL.createObjectURL(sound);
      audio.src = jam.url;
      jamApplyGain();
      renderJam();
      if (play) jamPlay();
    }

async function jamPlay() {
      const track = jamTrack();
      if (!track) { if (!jam.tracks.length) $('jamFolder').click(); return; }
      const audio = jamPlayer();
      if (!jam.url && !track.error) {   // still being measured or converted
        await waitUntil(() => jam.url || track.error || track !== jamTrack(), 120000);
        if (track !== jamTrack() || !jam.url) return;
      }
      if (track.error) return;
      try {
        if (jam.ctx.state === 'suspended') await jam.ctx.resume();
        await audio.play();
      } catch (err) {
        if (err && err.name !== 'AbortError') toast('This track does not play: ' + (err.message || err), 'error');
      }
    }

function jamStep(direction, play = null) {
      if (!jam.tracks.length) return;
      const audio = jamPlayer();
      const playing = play === null ? !audio.paused : play;
      if (direction < 0 && audio.currentTime > 3) { audio.currentTime = 0; return; }
      let index = jam.index;
      for (let tries = 0; tries < jam.tracks.length; tries++) {   // tracks that cannot be read are skipped
        index = (index + direction + jam.tracks.length) % jam.tracks.length;
        if (!jam.tracks[index].error) break;
      }
      jamLoad(index, playing);
    }

const jamClock = seconds => (Number.isFinite(seconds) ? Math.floor(seconds / 60) + ':' + String(Math.floor(seconds % 60)).padStart(2, '0') : '–:––');

function renderJamTime() {
      const audio = jam.audio;
      const at = audio ? audio.currentTime : 0, total = audio ? audio.duration : NaN;
      $('jamAt').textContent = jamClock(at);
      $('jamTotal').textContent = jamClock(total);
      $('jamSeekFill').style.width = (total > 0 ? clamp(at / total, 0, 1) * 100 : 0) + '%';
    }

function jamTrackNote(track, withTrim = true) {
      if (track.error) return track.error;
      if (!Number.isFinite(track.lufs)) return 'measuring …';
      const gain = jamGain(track), trim = jamTrim(track), bass = jamBass(track);
      return dbText(track.lufs) + ' LUFS · ' +
        (withTrim && Math.abs(bass) >= JAM_BASS_NOTE_DB ? (bass > 0 ? 'much bass ' : 'little bass ') + dbText(bass, true) + ' · ' : '') +
        (withTrim && trim ? 'by ear ' + dbText(trim, true) + ' · ' : '') + dbText(gain.db, true) + ' dB' +
        (gain.limited ? ' (its peaks allow no more)' : '');
    }

function jamTrackTip(track) {
      if (track.error || !Number.isFinite(track.lufs)) return '';
      const bass = jamBass(track), trim = jamTrim(track);
      return 'Loudness ' + dbText(track.lufs) + ' LUFS. Against a guitar its bass counts less: ' +
        (Math.abs(bass) < 0.05 ? 'that changes nothing here' : 'it plays ' + dbText(Math.abs(bass)) + ' dB ' + (bass > 0 ? 'louder' : 'quieter') + ' for it') +
        (trim ? ', and ' + dbText(Math.abs(trim)) + ' dB ' + (trim > 0 ? 'louder' : 'quieter') + ' by ear' : '') +
        '. Played at ' + dbText(jamGain(track).db, true) + ' dB.';
    }

function renderJam() {
      const dock = $('jamDock');
      dock.hidden = !jamStore.open;
      document.body.classList.toggle('jam-open', jamStore.open);
      const track = jamTrack();
      const playing = Boolean(jam.audio && !jam.audio.paused);
      $('jamBtn').classList.toggle('on', jamStore.open);
      $('jamBtn').classList.toggle('playing', playing && !jamStore.open);
      if (!jamStore.open) return;
      $('jamPlay').firstElementChild.style.setProperty('--icon', 'var(--ico-' + (playing ? 'pause' : 'play') + ')');
      $('jamPlay').classList.toggle('on', playing);
      $('jamTitle').textContent = track ? track.name : 'Choose the folder with your jam tracks';
      $('jamInfo').textContent = track ? (jam.index + 1) + ' / ' + jam.tracks.length + ' · ' + jamTrackNote(track, false) : '';
      const trim = jamTrim(track);
      $('jamTrim').textContent = dbText(trim, true);
      $('jamTrimBox').classList.toggle('set', Boolean(trim));
      $('jamTrimBox').classList.toggle('off', !track);
      $('jamTrimBox').title = !track ? 'A track\'s own correction' :
        'This track only, by ear: ' + (trim ? dbText(Math.abs(trim)) + ' dB ' + (trim < 0 ? 'quieter' : 'louder') + ' than its measured loudness asks for' : 'no correction') +
        '. Tracks at the same LUFS can still sit differently against a guitar. Remembered for this file' + (trim ? '; click the number to clear it' : '');
      $('jamRepeat').classList.toggle('on', jamStore.repeat);
      $('jamListBtn').classList.toggle('on', jam.list && jam.tracks.length > 0);
      const offset = jamStore.offset;
      $('jamLevel').textContent = dbText(jamTarget());
      $('jamLevelBox').title = 'How loud the tracks play: ' + (Math.abs(offset) < 0.05 ? 'as loud as' : dbText(Math.abs(offset)) + ' LU ' + (offset < 0 ? 'below' : 'above')) +
        ' your Drive presets (Auto level: ' + dbText(alTarget('drive')) + ' LUFS). A track\'s bass counts less in this' +
        (state.connected && Number.isFinite(state.usbReturnDb) && Math.abs(state.usbReturnDb) > 0.05 ? '. The Nano\'s USB playback volume of ' + dbText(state.usbReturnDb, true) + ' dB is made up for' : '');
      renderJamTime();

      const list = $('jamList');
      list.hidden = !(jam.list && jam.tracks.length);
      if (list.hidden) return;
      $('jamListTitle').textContent = jam.folder;
      const trimmed = jam.tracks.filter(item => jamTrim(item)).length;
      $('jamListSub').textContent = jam.tracks.length + ' track' + (jam.tracks.length === 1 ? '' : 's') +
        (jam.measuring ? ' · measuring ' + jam.measuring + ' …' : ' · levelled to ' + dbText(jamTarget()) + ' LUFS') +
        (trimmed ? ' · ' + trimmed + ' set by ear' : '');
      const select = $('jamOutput');
      select.innerHTML = '';
      select.appendChild(new Option('Output: this computer\'s', '', false, !jam.sink));
      jam.outputs.forEach(d => select.appendChild(new Option('Output: ' + d.label, d.deviceId, false, d.deviceId === jam.sink)));
      select.hidden = !jam.outputs.length;
      const rows = $('jamRows');
      rows.innerHTML = '';
      jam.tracks.forEach((item, i) => {
        const row = document.createElement('button');
        row.type = 'button';
        row.className = 'jam-row' + (i === jam.index ? ' sel' + (playing ? ' playing' : '') : '') + (item.error ? ' bad' : '');
        // the current track: a play symbol in place of its number
        row.innerHTML = '<span class="no">' + (i === jam.index ? '<span class="ico" style="--icon: var(--ico-play)"></span>' : i + 1) +
          '</span><span class="nm"></span><span class="lv"></span>';
        row.children[1].textContent = item.name;
        row.children[2].textContent = jamTrackNote(item);
        row.title = jamTrackTip(item);
        row.addEventListener('click', () => jamLoad(i, true));
        rows.appendChild(row);
      });
      const current = rows.children[jam.index];
      if (current && current.scrollIntoView) current.scrollIntoView({ block: 'nearest' });
    }
